window.POEM_DB=window.POEM_DB||{};POEM_DB["ming_034"]={"n":"吴与弼","dyn":"明","poems":[{"t":"秋晓","f":"五言绝句","c":["风来夜枕寒，云生晓窗雨。","旅思共秋清，遥思故山侣。"]},{"t":"晓立","f":"七言绝句","c":["灵台清晓玉无瑕，独立东风玩物华。","春气夜来深几许，小桃又发两三花。"]},{"t":"即事","f":"五言律诗","c":["吟断难成调，尘编重绎寻。","兴亡今古事，精一圣贤心。","新月何时满，寒蛩无数吟。","夜深双过鸟，犹自恋高林。"]},{"t":"感怀","f":"五言律诗","c":["人岁恒难百，光阴苦易过。","身心须点检，事业莫蹉跎。","豪俊今宁少，庸凡古亦多。","要知贤不肖，择术在如何。"]},{"t":"自警","f":"五言古诗","c":["读书悟至言，反躬屡紬绎。","颇谓无他岐，立可超凡域。","云胡心自戕，作事潜乖昔。","俯仰一长叹，惭惶竟何极。","乃知真切功，不可弛顷刻。","发愤矢自兹，群邪当远迹。","圣途虽渺茫，敢吝驽骀力。","诚当通鬼神，志当贯金石。"]},{"t":"族叔父仲学先生春月承访弼时赁房方定兹别数月矣有怀寄诗","f":"七言律诗","c":["忆昨烟花暖正繁，远劳玉趾到山间。","寓居踪迹应方定，入道工夫总未閒。","囊里有书供月眼，樽前无酒醉春颜。","别来新趣知多少，透彻灵台第几关。"]},{"t":"腊月望日作","f":"五言绝句","c":["欲到大贤地，须循下学工。","文章深讲贯，道德细磨砻。"]},{"t":"春夜","f":"七言律诗","c":["十年踪迹寓神州，故国归来更百忧。","事业有期空仰古，浮沉无计却随流。","谁怜白日难停驭，自觉秋霜易到头。","多少慇勤孤负也，欲从何处觅同游。"]},{"t":"宿白梅洲","f":"七言绝句","c":["道傍茅屋是谁家，薄暮东来一税车。","败壁不堪题姓字，时从篱槿看秋花。"]},{"t":"题柏","f":"七言绝句","c":["润色还因带雨荣，柔枝未许拂云横。","风霜莫厌多经历，自古良材老始成。"]},{"t":"过南康","f":"五言律诗","c":["迢递见危楼，家家枕碧流。","山高云气近，江阔浪声浮。","事业怀先哲，英雄慨昔游。","几多今古兴，斜日满芳洲。"]},{"t":"寄梁训导","f":"五言律诗","c":["未到都昌县，相思先计程。","连绵官舍饮，浩荡故乡情。","柳色雨来长，梅香霁后清。","极知期待远，别语细叮咛。"]},{"t":"闻笳","f":"七言律诗","c":["扁舟晴泊枉渚沙，苇苗满目稀人家。","夜江漠漠星横斜，东风吹鬓怜春华。","隔江谁舫寂无哗，数声悲响空中笳。","响彻碧霄哀更加，悠悠绿水天一涯。"]},{"t":"元日","f":"五言律诗","c":["淑气已回春，晴光遍八垠。","学须年共长，德必日俱新。","自得颜渊乐，宁论原宪贫。","两间期不愧，敢负百年身。"]},{"t":"赠别王上舍","f":"五言律诗","c":["旅馆相逢日，春风二月初。","看花杯共把，对月榻同铺。","礼乐沾清化，风云快壮图。","愿公多令誉，纲纪在人扶。"]},{"t":"与友人夜话","f":"五言律诗","c":["话尽情难极，中宵眠更兴。","古人俱已逝，后进竟何成。","世路应皆醉，吾侪岂独醒。","几回静想遍，无以答平生。"]},{"t":"梦洗马先生","f":"五言律诗","c":["先生天下士，遇我独情亲。","剪烛论心夜，焚香读易晨。","已私须尽克，天理必全纯。","惆恨春宵梦，分明笑语温。"]},{"t":"双燕春日营巢","f":"七言绝句","c":["忆昨初开桃李花，衔泥飞傍小窗斜。","春风一去无消息，何处归来更作家。"]},{"t":"山中歌次王右丞韵","f":"楚辞体","c":["地寥夐兮山深，聊栖迟兮林木。","欲寡过兮身轻，日往来兮幽谷。","行愧今兮交疏，心悲古兮趣独。","理桔槔兮灌园，更搴萝兮补屋。","晨光澹兮观鱼，夕阳收兮饮犊。","居从静兮积尘，岁愿丰兮登谷。","戒迂学兮徇名，嫌荒志兮干禄。","惟造道兮是期，何富贵兮可卜。"]},{"t":"山行","f":"五言律诗","c":["野水荒村僻，云林细路斜。","晴松张翠盖，秋果熟丹砂。","怅望淹乡曲，蹉跎改岁华。","西风吹薄袂，兴绪绕天涯。"]},{"t":"访胡徵君馆所","f":"五言律诗","c":["行客林边至，高人篱外迎。","远乘今日兴，细话旧时情。","凉夜一樽酒，清秋半壁灯。","相看惊老大，踪迹共浮萍。"]},{"t":"雨中漫述","f":"五言律诗","c":["违侍亲庭远，迁居此地新。","往来多故旧，问劳总比邻。","屋破长防雨，天寒早闭门。","卑栖聊自慰，图史共朝昏。"]},{"t":"松下","f":"七言绝句","c":["倦来更向山中憩，满径松阴白昼长。","藉地不知孤坐久，遗编又诵两三行。"]},{"t":"感兴","f":"七言绝句","c":["月到芭蕉影半斜，好天良夜兴无涯。","金风声满千竿竹，玉露光生一砌花。"]},{"t":"写怀","f":"五言律诗","c":["悠悠万古愁，瞑坐无一语。","志须自强持，仁拟谁相辅。","萧然环堵间，沉吟寸心苦。","荒村秋思多，断续芭蕉雨。"]},{"t":"登拟岘台","f":"五言律诗","c":["城据东南胜，台分襄楚名。","人烟萦近市，竹树杂长汀。","愁逐登临散，神因眺望清。","穷通看万物，未易达浮生。"]},{"t":"赠戴锦舟先生","f":"五言律诗","c":["尊酒黄城夜，交期是偶然。","文章元共赏，谈笑剧忘年。","近腊梅初放，凌寒菊正鲜。","同衾坐无寐，高兴两绵绵。"]},{"t":"题四景画 其一","f":"七言绝句","c":["草树风暄翠欲浮，洞门深处野花幽。","素琴不许闲人听，山自巍巍水自流。"]},{"t":"题四景画 其二","f":"七言绝句","c":["瀑洗层崖净世尘，阴阴苔径足南薰。","日长谁是山中伴，袖手前溪立白云。"]},{"t":"题四景画 其三","f":"七言绝句","c":["西风红叶绕苔矶，水冷烟寒雁正飞。","浮虑尽消身寂寞，得鱼无意起竿迟。"]},{"t":"题四景画 其四","f":"七言绝句","c":["村雪寒凝夜色浮，清江如玉着扁舟。","风流自得天然妙，心迹何曾泥去留。"]},{"t":"墨梅寄同安李宜之","f":"七言绝句","c":["学疏才薄谅何为，牢落尘踪阅岁时。","秪有梅花共心事，便风吹向故人知。"]},{"t":"晓","f":"五言律诗","c":["晓梦初惊觉，春禽已乱鸣。","北风半夜雨，东旭一窗晴。","道在心偏逸，诗成气转清。","行藏信随遇，庶以达吾生。"]},{"t":"题歙云诗卷","f":"五言律诗","c":["歙云南望迥，亲舍孝思深。","川陆几年客，晨昏千里心。","春风随使节，夜月照行襟。","养志古来重，功名好自任。"]},{"t":"送饶提举之官广东","f":"五言律诗","c":["奉节承深宠，之官过旧乡。","亲闱春广大，宦路日舒长。","岭树连云合，江流过雨凉。","倚门应有望，雁信好频将。"]},{"t":"读罢","f":"五言律诗","c":["隐几初收卷，巡檐更出行。","晚云随雨散，霁月近人明。","客久无违性，身閒独称情。","荣枯何足问，清白是家声。"]},{"t":"睡觉","f":"五言古诗","c":["午枕睡熟馀，情神喜宣朗。","窗含白日静，座纳微风爽。","俯披圣贤书，遗言如指掌。","至理谅易求，良心贵有养。","安得同志人，辅我加勉强。"]},{"t":"送严府判考满","f":"五言律诗","c":["柳绿绕江头，薰风快壮游。","万山辞楚徼，一水接皇州。","郡剧民俱化，铨明课最优。","垂衣图至治，清问有嘉猷。"]},{"t":"简戴锦舟先生","f":"五言律诗","c":["笔砚长为伍，思深趣转清。","看云閒隐几，听雨独挑灯。","俯仰求无愧，穷通不系情。","客边微恙在，襟抱贵和平。"]},{"t":"山中即事","f":"七言绝句","c":["水自幽偏山自深，竹窗花牖昼沉沉。","逢人若问浮生事，半是閒眠半是吟。"]},{"t":"晓出","f":"五言律诗","c":["际晓出柴扉，清凉过雨时。","落花香满径，芳树绿成帷。","鸟哢有馀暇，水流无尽期。","值予道心长，归咏正相宜。"]},{"t":"游广寿寺后园","f":"五言律诗","c":["新竹多垂箨，高花正满林。","云萝穿屈曲，苔径入幽深。","翠积丛茅暗，青交杂树阴。","剧便新结构，端称读书心。"]},{"t":"梦友","f":"五言律诗","c":["园林到何日，羁旅念离群。","扰扰一旬内，依依两梦君。","秋风黄叶下，晴色白云屯。","应有诗三百，心期欲细论。"]},{"t":"柬陈进士","f":"七言绝句","c":["独凭吟几坐清朝，閒看行云面碧霄。","忽忆故人秋寺里，西风琪树雨潇潇。"]},{"t":"彝公房","f":"五言律诗","c":["入院先看竹，逢僧不说经。","白云方丈室，清昼一孤灯。","积雨匀秋色，残阳报晚晴。","去留无定迹，香尽拂衣行。"]},{"t":"寄湖西族叔父仲学先生","f":"五言律诗","c":["茅屋石桥西，相亲记旧时。","青灯近人早，明月上窗迟。","物理推今古，人情较是非。","笑谈如昨日，寒暑几推移。"]},{"t":"赠别友人","f":"五言律诗","c":["惆怅一年别，慇勤百里来。","冰霜苦节在，宇宙壮怀开。","白雪传新卷，青春递客杯。","纷纷枫叶下，独伴野人回。"]},{"t":"阅九韶吟稿","f":"五言律诗","c":["高枕微吟罢，西斋独坐时。","閒澄病中思，细看别来诗。","点窜非吾事，渐磨贵自期。","灵台宜有养，孟子浩然师。"]},{"t":"别湖西","f":"五言律诗","c":["送送长村外，新诗咏不休。","浮云日色薄，随地露华稠。","曲径缘林转，深沟带叶流。","家山应暂住，更得话绸缪。"]},{"t":"同锁秀才道中即事","f":"五言律诗","c":["桑梓常留念，蹉蛇今始还。","行行减客路，望望近家山。","胶漆故人谊，风霜游子颜。","何能谢尘鞅，高卧白云閒。"]},{"t":"题庸轩","f":"五言律诗","c":["物理本平常，人心自渺茫。","细袪今古惑，多漱圣贤芳。","风月清江曲，园林古县傍。","悠悠百年兴，良与此轩长。"]},{"t":"禅岭即事","f":"五言律诗","c":["傍险跻攀倦，临高眺望赊。","天连苍野阔，树带小村斜。","晴霭山何处，寒烟屋数家。","踌躇怀往事，容易改年华。"]},{"t":"与钟生同宿东陂","f":"五言律诗","c":["日落辞莲塘，东陂到已暝。","烟雾村径微，灯花茅斋静。","细语夜卧迟，月华发清兴。","黄卷试一开，琅然共歌咏。"]},{"t":"夜访九韶","f":"五言律诗","c":["有客夜扣门，微吟带星立。","主人久青灯，欣然肃而入。","胜境失追攀，高堂更欢集。","丈夫襟抱开，尘绊嗟何及。"]},{"t":"赠九韶","f":"五言律诗","c":["我与生契家，恳恳常告戒。","退而省其私，立志能匪懈。","相逢索居后，新知颇超迈。","深培仁义根，势利无芥蒂。"]},{"t":"山居","f":"五言律诗","c":["偶坐柴门下，得与众山友。","雨后已芳润，云开更奇秀。","澹然忘我形，不觉沉吟久。","却忆平昔居，于兹几翘首。"]},{"t":"别九韶叔侄","f":"五言律诗","c":["我心日悠悠，喜与故人遇。","相随更过村，同游读书处。","研墨倩儿童，颇得临池趣。","青山一分手，山留白云去。"]},{"t":"即事","f":"五言律诗","c":["身外机事閒，心地何优游。","晴行山水曲，步迟境弥幽。","历乱高鸟过，散漫轻烟浮。","遗编幸在手，微意仍相侔。"]},{"t":"游南坑冈","f":"五言律诗","c":["松边涉幽径，天青雨新霁。","矫首立崇冈，叠嶂罗迢递。","尘虑都淡然，二仪足清气。","妙趣匪言传，飘飘离人世。"]},{"t":"夜坐","f":"五言律诗","c":["青灯夜已分，遗编味方永。","一唱而三叹，转觉寸心烱。","丽水金最精，蓝田玉偏瑩。","云胡苦茅塞，久未臻斯境。"]},{"t":"即事","f":"五言律诗","c":["风威遍野号，雪花满空坠。","谁谓惜苦寒，正喜兆丰岁。","红炉坐终日，黄卷静相对。","至哉圣贤言，妙契心自醉。"]},{"t":"感怀","f":"五言律诗","c":["孤灯读已倦，就床聊偃仰。","平生所践履，历历时在想。","中道立苦难，学问少勉强。","古人岂易期，中宵独惝恍。"]},{"t":"读孟子","f":"五言律诗","c":["夜气向虚朗，剪烛更已深。","大哉仁义言，沃我萌蘖心。","才质各高下，性命无古今。","圣贤恳垂训，而我何陆沉。"]},{"t":"睡起","f":"五言律诗","c":["久客逢寒食，芳年损病心。","几时鸣雨歇，终日落花深。","亲梦凝官舍，乡魂绕故林。","昼长春睡起，寂寂写孤吟。"]},{"t":"閒述","f":"五言律诗","c":["静里生诗思，閒中长道心。","自应尊椟玉，不省说籯金。","芳树流春色，空庭落午阴。","日和风更澹，此乐有谁寻。"]},{"t":"承叶别驾见访奉柬二首 其一","f":"五言律诗","c":["窗下书生报，门前使客临。","形容惊喜定，情话别离深。","风月江山趣，冰霜松柏心。","平生觅同调，几处得知音。"]},{"t":"承叶别驾见访奉柬二首 其二","f":"五言律诗","c":["白雪阳春调，长吟莫厌多。","功夫既积累，律吕自谐和。","江海犹疏凿，圭璋藉琢磨。","人生谁不学，志向各如何。"]},{"t":"忆荣上舍","f":"五言律诗","c":["江馆春相遇，乡心晚益知。","青云持节日，短褐省亲时。","高谊能分禄，空囊只赠诗。","别来消息断，几欲到分宜。"]},{"t":"买药","f":"五言律诗","c":["生涯惟病绊，人事与心违。","岁月一身晚，江湖孤梦飞。","忧深多为道，贫惯任无衣。","抱布街头去，新晴买药归。"]},{"t":"即事","f":"五言律诗","c":["欲识阳和景，四时惟有春。","风光三月半，霁色独吟频。","露叶浑如醉，烟花不择贫。","人心长自小，宁解化工仁。"]},{"t":"感怀","f":"五言律诗","c":["易白颜回发，难升孔子堂。","常时思寡过，终岁未成章。","万物人皆备，一心谁不良。","如何空潦倒，甘让昔贤芳。"]},{"t":"绝句","f":"七言绝句","c":["新诗尽日恣冥搜，尘世悠悠任去留。","兴到江山随处览，不知身外有閒愁。"]},{"t":"杨柳","f":"五言律诗","c":["婵娟杨柳枝，烟雨涵芳姿。","托根近孤松，苍翠相因依。","颇谓颜色好，可同岁寒期。","岂知霜未坠，素叶先纷飞。"]},{"t":"圃内","f":"五言律诗","c":["长夏日已晚，归鸟皆投林。","幽独悦兹圃，把书行且吟。","花竹流芳净，蔬果生意深。","两间有妙趣，长契静者心。"]},{"t":"四月四日","f":"五言律诗","c":["客床起复眠，中心怅遐慕。","嗟我庭中亲，兹旦惟初度。","岂独别离深，鬓发久垂素。","形留空役神，迢迢滞江路。"]},{"t":"宿章广文馆","f":"五言律诗","c":["虚斋罢清话，拂床事枕席。","青灯灭馀烬，斜月流素壁。","弟子富书声，感之增叹息。","沉痾久缠绵，那由共兹夕。"]},{"t":"赠章广文","f":"五言古诗","c":["俗情素寡合，独往欲无言。","伊谁写湮郁，喜得章澹然。","丝萝托世好，金兰契忘年。","青眼饶故意，白云多新篇。","顾兹蹉跎志，怀古共勉旃。"]},{"t":"茂树","f":"五言律诗","c":["古垣有茂树，婆娑广成帷。","霜雪根本固，雨露枝叶肥。","蒙密自昏晓，静爱众鸟归。","此物尚有容，吾心谅何为。"]},{"t":"月夜忆友人","f":"五言律诗","c":["阶除境向寂，客思渺无依。","美兹风月夕，正是怀人时。","欲叙平生心，相见各未期。","百年若流水，如何长别离。"]},{"t":"题画马","f":"五言古诗","c":["有客遣弟子，持示双马图。","丹青固妙笔，所拟皆龙驹。","一龙嘶青云，一龙困盐车。","逸气含变态，病骨森清癯。","既遭伯乐顾，绝足乃得纾。","未遇善自保，饱秣青山刍。"]},{"t":"游北禅寺","f":"五言律诗","c":["入门闻花香，傍砌看花色。","花香细而清，花色洁以白。","薰风院深沉，亭午人閒寂。","悠哉羲皇上，着此忘机客。"]},{"t":"栖凤竹","f":"五言绝句","c":["庭宇肃深沉，苍翠交梧竹。","众鸟从纷飞，时看凤来宿。"]},{"t":"送人赴春闱","f":"五言律诗","c":["画省身先达，春闱气正豪。","功名方自负，关塞岂辞劳。","黄道中天近，青云北极高。","胪传知得意，端笏继夔皋。"]},{"t":"柬朱学正先生","f":"五言律诗","c":["伊昔起予深，相逢久别心。","老成欣德重，薄劣愧年侵。","夜雨添新思，秋风忆旧吟。","正期谈笑密，还念欲分襟。"]},{"t":"不寐","f":"五言律诗","c":["寒鼓三更后，孤衾未睡时。","无穷身外事，逐一静中思。","圣域何由入，灵台久自私。","疏棂霜月白，愁况漫裁诗。"]},{"t":"览旧游","f":"七言绝句","c":["高树春风花正开，芒鞋曾记屡徘徊。","如今花落年光莫，寒色斜阳又独来。"]},{"t":"山中见梅花","f":"七言绝句","c":["茅庵深处路萦斜，老树遥看近腊花。","何事幽人吟未到，游蜂先已得春华。"]},{"t":"述怀","f":"五言律诗","c":["风雨春天晓，江山客梦醒。","浮沉谁共慰，出处独含情。","得善惭颜氏，传经忆伏生。","经过人事略，何意钓时名。"]},{"t":"春夜","f":"七言绝句","c":["千古兴怀洙泗滨，无由一接杏坛春。","自怜弱质生来晚，空作纷纷世上人。"]},{"t":"忆九韶","f":"七言古诗","c":["春泥滑滑阴连朝，出门跬步难逍遥。","阳和黯然舒蔼蔼，风雨倏忽来萧萧。","客怀思见故人面，云山阻绝谁相招。","故人隐居萝溪曲，残书破砚甘寂寥。","奉亲常惧岁月速，学古不使子弟骄。","躬耕低头秋谷熟，击壤皞皞歌唐尧。","平生于我谊不薄，松柏宁向秋风凋。","愧我崎岖昧生理，托身在处云飘飘。","何时归来葺茅屋，与子共种黄精苗。"]},{"t":"出城","f":"五言律诗","c":["行行共吾侄，诵诗出城郭。","白日皎青天，风光胜于昨。","岭外更峰峦，村边总花萼。","扰扰行路人，谁识予心乐。"]},{"t":"新庄渡","f":"五言绝句","c":["渡头舟已发，随意坐芳洲。","白石聊为砚，题诗蘸碧流。"]},{"t":"道中作九首 其一","f":"五言绝句","c":["临渠爱流水，试砚涉还歇。","起看碎米花，疑残去年雪。"]},{"t":"道中作九首 其二","f":"五言绝句","c":["眺望觉日迟，经过忘前后。","牧唱儿童閒，黄牛满丘阜。"]},{"t":"道中作九首 其三","f":"五言绝句","c":["丛竹夹桃花，清池映高下。","世上有丹青，笔底谁能画。"]},{"t":"道中作九首 其四","f":"五言绝句","c":["爱景时回立，烟村澹相对。","惆怅百年人，此心几人会。"]},{"t":"道中作九首 其五","f":"五言绝句","c":["呼童汲清泚，怡然坐临池。","谁能知我怀，细雨来催诗。"]},{"t":"道中作九首 其六","f":"五言绝句","c":["人生得丈夫，万一幸为儒。","寸心含宇宙，不乐复何如。"]},{"t":"道中作九首 其七","f":"五言绝句","c":["纸笔不暂离，琴书恒自随。","欲忧身外事，何日是閒时。"]},{"t":"道中作九首 其八","f":"五言绝句","c":["得诗万事轻，性达频爵跃。","翘首吟未回，松风度寥廓。"]},{"t":"道中作九首 其九","f":"五言绝句","c":["微雨已滑途，行客未堪住。","遥问读书斋，正在花深处。"]},{"t":"友人至","f":"五言绝句","c":["独绕烟村来，共兹玩云月。","细雨夜已阑，深意殊未歇。"]},{"t":"晓起即事 其一","f":"五言绝句","c":["夜思经世务，神倦方熟眠。","晨朝气清爽，良心还烱然。"]},{"t":"晓起即事 其二","f":"五言绝句","c":["条风暖雨来，晨烟村冥漠。","北牖时独开，纷纷李花落。"]},{"t":"录诗稿","f":"五言绝句","c":["晴日鸟相唤，轻风花乱飞。","红尘休入户，次第正抄诗。"]},{"t":"客玩夜月","f":"五言绝句","c":["静来悟道机，窔奥难言说。","但得此心安，从处堪乘月。"]},{"t":"纵步","f":"五言绝句","c":["幽花发清香，芳林涨新绿。","閒听山中禽，更倚篱边竹。"]},{"t":"友人至 其一","f":"五言绝句","c":["整屦欲有往，故人忽西来。","盎然阳春怀，共向东风开。"]},{"t":"友人至 其二","f":"五言绝句","c":["平生慕克己，茫然靡所获。","今日欣语君，至乐颇洋溢。"]},{"t":"觉后","f":"五言绝句","c":["觉来气宇澄，开牖东林下。","缺月五更头，寒光皎清夜。"]},{"t":"村中即事","f":"五言绝句","c":["春光被四野，行欣物华茂。","寂寂竹林边，幽禽语清昼。"]},{"t":"胡十见访客馆值予暂出承候迎村外遂相与叙旧同宿得诗六首 其一","f":"五言绝句","c":["归步夕阳迟，和风满襟袖。","矫首清溪傍，芳畦故人候。"]},{"t":"胡十见访客馆值予暂出承候迎村外遂相与叙旧同宿得诗六首 其二","f":"五言绝句","c":["梅花残腊时，访予五峰上。","讵知萍梗踪，春光此同赏。"]},{"t":"胡十见访客馆值予暂出承候迎村外遂相与叙旧同宿得诗六首 其三","f":"五言绝句","c":["我归惊十年，回首如信宿。","惆怅谪仙吟，人生鸟过目。"]},{"t":"胡十见访客馆值予暂出承候迎村外遂相与叙旧同宿得诗六首 其四","f":"五言绝句","c":["忆子有立年，曾与论耿介。","吾今越斯境，事业怜安在。"]},{"t":"胡十见访客馆值予暂出承候迎村外遂相与叙旧同宿得诗六首 其五","f":"五言绝句","c":["既罢溪上游，复向篱边坐。","夜景良可人，谁能即高卧。"]},{"t":"胡十见访客馆值予暂出承候迎村外遂相与叙旧同宿得诗六首 其六","f":"五言绝句","c":["交期相惠好，青灯共斯阁。","话言杂今昔，心事兼悲乐。"]},{"t":"昼寝觉","f":"七言绝句","c":["日净风暄清昼迟，绿阴啼鸟梦醒时。","间窗笔砚无尘杂，幽事宜人又得诗。"]},{"t":"读中庸","f":"五言绝句","c":["一理存乎静，万事著于微。","是以君子心，战兢恒自持。"]},{"t":"弹琴","f":"五言绝句","c":["寂寥春夜间，几阁孤灯照。","邈尔形役忘，丝桐正清妙。"]},{"t":"琴罢","f":"五言绝句","c":["琴罢诗兴来，残灯独挥笔。","因识圣人心，澹然何意必。"]},{"t":"别锁秀才","f":"五言律诗","c":["觅渡临清流，故人更同舟。","细语昨日诗，别怀总悠悠。","送送山之麓，春花多踯躅。","长揖东风前，浮生两相勖。"]},{"t":"梦严亲","f":"五言律诗","c":["江山久离居，薄养那得及。","髣髴何处庭，承颜梦中立。","天性良固有，深爱成长泣。","涕泪泫莫收，晓起衾犹湿。"]},{"t":"牛氏东轩","f":"五言绝句","c":["名花散奇香，幽苔多净绿。","清昼轩中人，琴书自相续。"]},{"t":"感旧游","f":"七言绝句","c":["石桥门巷落花深，晴日光风鸟乱吟。","人事暗随春梦换，绿杨还似旧时阴。"]},{"t":"柬徐广文","f":"古风","c":["学问无少长，立志夫何如。","勉强柔即强，惰慢明亦愚。","光景勿云盛，容易垂桑榆。","年侵勿自画，为仁果谁欤。","一私诚自窒，荡荡斯广居。","深切累日月，圣贤途岂殊。","勉旃黉宫彦，勇往毋踟蹰。","莫嫌??言，素心不能谀。"]},{"t":"上顿渡舟中","f":"七言绝句","c":["驱驰年少未应劳，万事无心任所遭。","收拾琴书辞故郡，江山随处是诗豪。"]},{"t":"夜坐","f":"五言绝句","c":["雨滴空阶响，灯悬净壁明。","掩书人独坐，性达正惺惺。"]},{"t":"蕲春采芹亭同罗黄二广文登","f":"五言律诗","c":["名亭极虚敞，英友携登临。","石池湛寒水，茂树围幽阴。","久坐得胜趣，剧谈延赏心。","薄游庆佳遇，因以书狂吟。"]},{"t":"题一丘轩","f":"五言绝句","c":["种此一丘田，朝夕恒精虔。","众草不敢秽，瓜瓞斯绵绵。"]},{"t":"寄胡九韶","f":"五言古诗","c":["去家已十日，作客无尽期。","悟道达浮生，浩荡随所之。","荣枯藐毫忽，得失轻铢锱。","闻味圣贤道，谩吟今古诗。","胜境多独得，佳兴良自知。","寄言故乡友，身心善矜持。"]},{"t":"谒濂溪晦庵二先生祠二首 其一","f":"七言绝句","c":["孔孟微言几欲绝，先生千载续真传。","偶经灵宇增新感，遗绪寥寥苦简编。"]},{"t":"谒濂溪晦庵二先生祠二首 其二","f":"七言绝句","c":["平生慨慕古人深，道味先生更所钦。","长恨无缘趋末席，灵祠一拜俨如临。"]},{"t":"梦亲","f":"五言绝句","c":["欲写离肠苦，无言下笔难。","奉欢何日遂，梦里暂承颜。"]},{"t":"登舟入楚","f":"七言绝句","c":["步出湓城吊古馀，前程又复即舟居。","客身到处无荣辱，随分萧条两箧书。"]},{"t":"梦慈闱","f":"七言绝句","c":["昊天罔极裂心肝，遗冢荒凉不忍看。","魂梦岂知生死隔，承颜浪喜得真欢。"]},{"t":"即事","f":"七言绝句","c":["吟觉多情坐不眠，月光涵水水浮天。","橹声细与歌声协，又有西来夜泊船。"]},{"t":"观濂洛关闽诸君子遗像","f":"五言古诗","c":["平生习迂僻，人物常怀古。","自从尧舜来，历历固可数。","降兹秦汉下，无才继邹鲁。","伟哉宋德隆，夫子生四五。","日月丽中天，远近曷不睹。","人心一返正，斯道朗以溥。","嗟我小子愚，私淑岂小补。","偶从黄卷中，瞻像慰渴慕。","因像以求心，益自陶莽卤。","不及犹恐失，谁知此心苦。","会当写斯图，顷刻恒敬负。"]},{"t":"读易","f":"五言古诗","c":["夏日舒以长，斋内深更静。","正襟新浴馀，肃容湛天性。","悠哉四圣心，玩味频起敬。","好风生坐隅，竹色鲜相映。","澹尔绝外牵，伊谁共佳兴。"]},{"t":"枕上绝句","f":"七言绝句","c":["贤圣微言玩愈精，夜分无寐独惺惺。","十年醉梦迷南北，一点寒山雪后青。"]},{"t":"即事","f":"七言绝句","c":["环堵萧然隔世尘，日长惟有简编亲。","青衿髦士时能访，出处谆谆话古人。"]},{"t":"晓起即事","f":"五言律诗","c":["人心秉至灵，胡为自狼狈。","十年磨一镜，渐觉尘埃退。","清晓旭日升，竹树欣相对。","欲记丹青图，斯意恐难会。"]},{"t":"黄广文为仆趣装","f":"五言律诗","c":["客子去莫留，故人情不浅。","离合焉足论，事业宜加勉。","恒令此志存，会见长材展。","贤圣以为师，任重而道远。"]},{"t":"黄广文城外送别","f":"五言绝句","c":["迢递步暑来，高情重为别。","匆匆话莫穷，努力男儿节。"]},{"t":"宿渐岭","f":"七言绝句","c":["漠漠暮林横绿野，澄澄秋水映红云。","远来客舸依沙岸，独犬一声何处村。"]},{"t":"赤壁怀古","f":"五言绝句","c":["今日题诗处，明朝迹又尘。","不知江汉水，流尽几多人。"]},{"t":"大冶山中","f":"五言绝句","c":["客路逢人问，前程去已迷。","唤回琴剑侣，斜度小桥西。"]},{"t":"重访盛山人","f":"五言律诗","c":["舍馆曾留宿，园林今更过。","米嫌秋熟少，苗叹雨伤多。","寄远书应达，移居事若何。","秋风凉冷后，有待碧山阿。"]},{"t":"谢家埠舟中即事","f":"七言绝句","c":["忆昔扁舟久寓居，客中风景自能摹。","重来几换人间节，佳兴如今却胜初。"]},{"t":"次梅根","f":"七言绝句","c":["风色萧萧生暮寒，月明催棹下奔湍。","孤舟系稳更相劳，又得长江一日安。"]},{"t":"舟中即事","f":"七言绝句","c":["缃帙收来霜夜分，月中犹见打鱼人。","始知各有平生分，勤苦方能立此身。"]},{"t":"荻港舟中","f":"七言绝句","c":["寒芦漠漠夜澄澄，云尽霜天月倍明。","欲问个中深浅兴，青灯孤映读书声。"]},{"t":"舟次芜湖寄友","f":"七言绝句","c":["地迥天清芦雁呼，西风残照泊芜湖。","远书不尽悠悠意，努力人间大丈夫。"]},{"t":"述怀","f":"七言绝句","c":["平生踪迹惯飘蓬，短棹从教西复东。","借问乡园从别后，一旬清思属中庸。"]},{"t":"偶述","f":"七言绝句","c":["十年勤苦学求仁，品汇纷纭未识真。","惟有一般堪自笑，行藏酷过古人贫。"]},{"t":"舟中观书忆诸生","f":"五言律诗","c":["灯火夜常半，工夫日又新。","滥追先进躅，频忆故山人。","冻竹那妨雪，寒梅自有春。","此生何处达，天地即吾仁。"]},{"t":"别史仪部","f":"五言律诗","c":["清誉闻来熟，高情交更深。","青灯连夜话，黄卷百年心。","斯道何难入，深功贵自任。","匆匆惭赠纻，惆怅托狂吟。"]},{"t":"别李凤仪","f":"五言律诗","c":["途逢浑似梦，惊定始开襟。","万里又分袂，几时重盍簪。","诗书仍努力，穷达莫殊心。","邈尔云山外，频频忆旧吟。"]},{"t":"访叶别驾","f":"五言律诗","c":["消息犹难得，逢迎更敢期。","宁知为客际，重悉久要辞。","剪烛嫌更短，连床愿别迟。","欲投迂阔分，舍此复何之。"]},{"t":"赠丁太常","f":"五言律诗","c":["别驾侨居处，频过不觉疲。","喜通仪部好，更辱太常知。","贱子惭何算，明公贵有为。","圣途如指掌，努力妙年时。"]},{"t":"宿黄茅潭隔港","f":"五言绝句","c":["日夕北风起，停桡未有涯。","横江欣得伴，和月宿芦花。"]},{"t":"偶述","f":"五言绝句","c":["欲遵君子业，名教贵昭融。","能事参天地，元基慎独功。"]},{"t":"板桥客夜","f":"七言绝句","c":["达得浮生去住轻，江楼遇夜旅魂清。","远书作罢孤灯静，霜月凄凉雁数声。"]},{"t":"除日书怀","f":"七言绝句","c":["一岁生涯不离书，明年行止更何如。","男儿挺拔今犹古，百倍工夫正属渠。"]},{"t":"除夜次唐人诗韵","f":"七言绝句","c":["青灯幽户照无眠，高兴吟哦正浩然。","一岁平安私自幸，进脩踊跃入新年。"]},{"t":"西轩即事","f":"七言绝句","c":["冻消残雪早春回，幽户条风任往来。","黄卷玩馀閒卧后，满窗春色数枝梅。"]},{"t":"观梅","f":"七言绝句","c":["梅花满眼感怀新，正月俄惊十日春。","花落更开开更落，小窗忙杀读书人。"]},{"t":"柬友人 其一","f":"七言绝句","c":["物物由来根太极，等閒那得识其真。","浮生三十端虚度，扰扰俱为梦里人。"]},{"t":"柬友人 其二","f":"七言绝句","c":["贫居尽日掩柴关，黄卷青灯不敢閒。","克己转知前日妄，希贤愈觉古人难。"]},{"t":"感兴","f":"七言绝句","c":["浮生岁月易蹉跎，交谊知心苦不多。","几欲开怀难觅伴，只应怀古独高歌。"]},{"t":"赠黄经历先生","f":"五言律诗","c":["竹屋长无雁，花封偶盍簪。","雨窗宵并榻，雪案昼同吟。","往事浑如梦，清欢暂称心。","明朝踏晴色，归思各云林。"]},{"t":"题琴乐轩","f":"七言律诗","c":["花县东南里巷深，高轩清乐属瑶琴。","绿阴帘幕閒中世，明月阶除静里心。","松韵正幽孤鹤唳，海涛初定老龙吟。","山中亦有无弦趣，茅屋何时肯一寻。"]},{"t":"梦亲","f":"五言绝句","c":["夜夜春天梦，依依只在亲。","山中有茅屋，何日溯归津。"]},{"t":"题三友图","f":"七言绝句","c":["桃李春晴锦万堆，萧然谁数竹松梅。","不因处士开新画，雪里何从表异材。"]},{"t":"严亲寄家谱至","f":"七言绝句","c":["门外欢声送喜来，天边家谱到山开。","音尘已隔半年后，乐极犹疑是梦回。"]},{"t":"南轩夜坐","f":"五言古诗","c":["庭前诗已成，云间月未没。","入户启南轩，无拘转真率。","草木发天香，遥夜清人骨。"]},{"t":"奉寄黄浩中先生","f":"七言绝句","c":["十年两度侍西轩，细语倾心夜不眠。","浮世别离疲野马，几回怀古独云天。"]},{"t":"月夜","f":"七言绝句","c":["迢迢良夜月澄秋，万象清严风露幽。","安得人心亦如此，廓然欲尽理周流。"]},{"t":"题梅竹轩","f":"七言律诗","c":["莲塘南畔碧山连，梅竹幽深着小轩。","接席好风晴满径，隔帘香雪夜浮天。","题诗兴绕赓歌际，读易心游未画前。","佳致几时期我共，为君细和白云篇。"]},{"t":"暂宿新居","f":"五言古诗","c":["青山白云里，旷然露平陆。","峰峦森远近，涧溪罗屈曲。","辛丑杪秋中，相基蒙吉卜。","明年闰月冬，于焉结新屋。","癸卯建未初，移居遂所欲。","藩篱虽未稠，斗室聊自足。","露坐天宇凉，语笑偕僮仆。","共想古昔来，谁人此曾宿。"]},{"t":"东轩即事","f":"五言古诗","c":["公事缠弥旬，寸心靡敢放。","岂惟学古难，人欲诚易荡。","昨宵拟见官，风雨不成往。","偶此东窗下，暂然閒俯仰。","遍阅旧时吟，静思新志向。","疑似寔自蒙，伊谁一指掌。","洙泗迹既陈，洛闽且绝响。","安得同志人，灵台期共养。"]},{"t":"十一月朔旦枕上作","f":"七言绝句","c":["立志成人自稚年，中间卤莽实堪怜。","如今转觉人须学，截日严程造白坚。"]},{"t":"除夕","f":"五言律诗","c":["慷慨临除夕，蹉跎又见春。","一年非不学，何日是成人。","经事才还广，潜心理渐真。","微吟增感激，名教定书绅。"]},{"t":"伤农家","f":"五言绝句","c":["秋谷应多减，春炊固转艰。","频闻寒雨里，采蕨满深山。"]},{"t":"十二月十四日绝句 其一","f":"七言绝句","c":["弊庐风雨何曾蔽，衣食田园给更悭。","积病寒窗尘满眼，始知无怨实为难。"]},{"t":"十二月十四日绝句 其二","f":"七言绝句","c":["始知无怨实为难，至乐谁如孔与颜。","误把古人轻易看，精脩从此可容閒。"]},{"t":"十二月十四日绝句 其三","f":"七言绝句","c":["精脩从此可容閒，勘破当年义利关。","随处动心兼忍性，何忧不到古人班。"]},{"t":"十二月十四日绝句 其四","f":"七言绝句","c":["何忧不到古人班，只把遗经子细看。","学久自然查滓化，心斯广矣体斯胖。"]},{"t":"惧衰","f":"七言绝句","c":["少壮空缠疾病过，光阴况复迅如梭。","蹉跎容易入衰境，此德此身将奈何。"]},{"t":"寒疾未醒兼困于疮废书默咏朱子及陆象山兄弟鹅湖倡和诗僭次其韵","f":"七言律诗","c":["先哲高风悉所钦，考亭朱子益留心。","沧溟浩浩吞诸水，泰华巍巍失万岑。","理极研精无窔奥，形纯践履更深沉。","微躯每恨生来晚，空慕声容隔古今。"]},{"t":"除夜","f":"七言绝句","c":["一年程课更如何，轻薄还因感慨多。","明日又逢新岁月，几时能出旧巢窠。"]},{"t":"元日","f":"七言绝句","c":["回首流年一梦间，静思身世立应难。","工夫百倍须深勉，莫把光阴当等閒。"]},{"t":"正月十九夜枕上作 其一","f":"七言绝句","c":["自叹生来后圣贤，下流入道苦难前。","何由养得中和性，乐以忘忧理浑然。"]},{"t":"正月十九夜枕上作 其二","f":"七言绝句","c":["乐以忘忧理浑然，后生岂易造斯言。","敛然下学无他法，一味深功克性偏。"]},{"t":"书所得","f":"七言绝句","c":["荆棘场中二十年，中间回首实堪怜。","欲从何处求心性，日用由来总是天。"]},{"t":"舟宿陶婆湾","f":"七言绝句","c":["夜半扁舟梦不成，细将心绪绎平生。","人伦有道何能尽，展转无端感慨情。"]},{"t":"赠九韶","f":"七言律诗","c":["绿萝溪上旧儒家，脩竹乔松去市赊。","南亩秋风多熟黍，东园夜雨总肥瓜。","圣贤指示方应密，师友相期路不差。","孝友一门斯是政，读书声里老生涯。"]},{"t":"夜读康节先生诗后作","f":"七言律诗","c":["田圃工夫日破除，小窗灯火夜诗书。","月华皎洁云轻后，夏景清凉雨霁馀。","百体无拘知气泰，一尘不累识心虚。","从今莫惜慇勤学，好古方能屡起予。"]},{"t":"梦傅秉彝","f":"七言绝句","c":["一别那胜岁月深，浮沉世务阻相寻。","分阴痛惜平生志，梦里犹悬怅怏心。"]},{"t":"午枕","f":"七言绝句","c":["枕簟清凉午梦浓，觉来鸠语太从容。","寸心似水无纤浪，认取邹书夜气功。"]},{"t":"夏夜","f":"七言绝句","c":["月色婵娟夜正凉，偶然徐步稻花傍。","篱多竹树饶清荫，池满芙蕖有暗香。"]},{"t":"寄九韶","f":"七言绝句","c":["幽窗遗籍自朝昏，尽日红尘不到门。","顽钝淬磨还有益，新功频欲故人闻。"]},{"t":"月夜","f":"五言绝句","c":["凉月清襟抱，閒吟气正和。","熟思刚暴性，旦昼梏亡多。"]},{"t":"夜读后对月","f":"七言绝句","c":["青灯读倦阁遗编，见月多情又不眠。","欲识此心虚妙处，沉沉户牖嫩凉天。"]},{"t":"省己","f":"七言绝句","c":["希贤事业愧庸才，煅炼磋磨志愈乖。","世泽厚深流庆远，道心连日得悠哉。"]},{"t":"月夜","f":"七言绝句","c":["云尽天心月正圆，可人清景属南轩。","满怀今古那能寐，缓拭枯桐理舜弦。"]},{"t":"变化气质消磨习俗","f":"七言绝句","c":["由来气质已偏枯，俗染弥深愈失初。","于此不加鏖战勇，却从何处着工夫。"]},{"t":"观旧稿","f":"七言绝句","c":["十载飘零无定栖，两年幸隐此山扉。","诗书渐觉添新得，心性还应胜旧时。"]},{"t":"寄题戴氏水竹居","f":"五言古诗","c":["胜日来良朋，相招出茅屋。","壮观穷名山，所历清心目。","山人白云端，苍翠罗脩竹。","鹤发笑相逢，坐谈此君熟。","苔径递幽阴，轩楹净如玉。","尘虑蝉已蜕，道心露新沐。","主宾偶一契，题诗惬素欲。","徘徊话别迟，夤缘看未足。","归卧梅窗云，馀兴犹可掬。","何当载酒来，重寻咏淇澳。"]},{"t":"有悟","f":"七言绝句","c":["困穷拂乱力难胜，天意分明增不能。","思到此心收敛处，聪明睿知自然生。"]},{"t":"除夜 其一","f":"七言绝句","c":["不惑无闻大圣辞，如今秪有五年期。","譬犹万里关山路，驽足应须日夜驰。"]},{"t":"除夜 其二","f":"七言绝句","c":["驽足应须日夜驰，丁宁莫枉一男儿。","工夫彻后开眉看，万里青天月出时。"]},{"t":"元日","f":"七言绝句","c":["去年程课略加勤，今岁深期日日新。","万事何如吾道重，丁宁莫枉此生身。"]},{"t":"遣闷","f":"七言绝句","c":["讲学无功德不脩，不才甚矣可无忧。","青春回首今何在，堪叹人生易白头。"]},{"t":"发舟弓家渡","f":"七言绝句","c":["囊书喜上省亲舟，千里山川尽旧游。","家庆新欢堪计日，前程渐次减离忧。"]},{"t":"赠傅秉彝","f":"七言绝句","c":["洗墨池边春草长，重来怀旧意茫茫。","蹉跎容易青春晚，秋鬓能禁几点霜。"]},{"t":"清苦吟","f":"五言绝句","c":["清苦丈夫志，风霜善自持。","阳和非不爱，义命贵安之。"]},{"t":"即事","f":"七言绝句","c":["磊落群峰彻晓云，柴关閒出为晴曛。","逢人偶学占秧候，活水渠边手自分。"]},{"t":"昼坐外南轩","f":"七言绝句","c":["南窗北牖透晴光，花木参差日正长。","举目无非幽赏处，不知何地是仙乡。"]},{"t":"绝句","f":"五言绝句","c":["竹户风光软，花轩清昼迟。","苍苔人迹绝，净几独吾伊。"]},{"t":"閒趣","f":"七言绝句","c":["野水云山隔市尘，日凭閒散养吾真。","茅庐周匝多芳树，行处清香暗袭人。"]},{"t":"梦觉作","f":"七言绝句","c":["静夜迢迢独觉时，寸心凝敛绝邪思。","聪明睿知何从出，作圣之功信在斯。"]},{"t":"纱陂","f":"五言绝句","c":["长潴石罅冰，广浣溪中雪。","清风生夜寒，泓澄浸秋月。"]},{"t":"大同峡","f":"五言绝句","c":["秀峙交翠屏，清冷响寒玉。","谷鸟时一鸣，苍苔此幽独。"]},{"t":"晓起","f":"五言绝句","c":["夜气春融和，曙光晴皎洁。","漠漠碧云端，斜露清霄月。"]},{"t":"罗家园","f":"五言绝句","c":["湛湛芳草池，翛翛碧霄竹。","倚竹漱春流，清气满幽谷。"]},{"t":"李家山","f":"五言绝句","c":["携琴兼载酒，童冠偕跻攀。","浩歌碧云里，落日松风寒。"]},{"t":"徐家山","f":"五言绝句","c":["大路临青山，苍苔荫清樾。","几度纵芒鞋，送宾此为节。"]},{"t":"石泉","f":"五言绝句","c":["石泉千古名，悠悠四时绿。","清洁乃素心，白云一茅屋。"]},{"t":"东陂","f":"五言绝句","c":["迢迢透长源，滔滔流昼夜。","几曾瞑目听，应悟安行者。"]},{"t":"东窗诵陶诗","f":"五言律诗","c":["时和风雨调，绿畴日滋长。","吾意良淡然，晴窗坐虚敞。","竹荫连琴书，幽苔隔尘鞅。","流诵徵君辞，伊谁嗣清响。"]},{"t":"偶书","f":"七言绝句","c":["倦出寻常止茅屋，妄想潜消思寡欲。","但恨青山云未深，更欲移居问穷谷。"]},{"t":"枕上作","f":"五言律诗","c":["为学旷锄犁，事农疏典籍。","学弛心性芜，农惰饥冻逼。","二者贵兼之，庶几日滋益。","奈何疾病缠，蹉跎旦复夕。"]},{"t":"即事","f":"楚辞体","c":["独步孤村去，从容玩我书。","稻苗时雨后，山色晚晴馀。","性也何曾染，心兮此正虚。","归来带明月，夜兴更何如。"]},{"t":"灯下作","f":"五言绝句","c":["日日劳筋骨，心中未免疑。","细思贫贱理，素位合如斯。"]},{"t":"赠黄徵士","f":"五言古诗","c":["卧疴白云中，苦心正怀旧。","忽枉故人盼，青山得携手。","晴窗坐南薰，薄言劝春酒。","眷然惜离群，问答殊未久。","荒村多寂寥，还能重来否。"]},{"t":"写怀","f":"七言绝句","c":["意绪依依万感馀，羸躯应向死边苏。","哀歌欲写难成调，几傍霜檐对月孤。"]},{"t":"冬夜枕上作","f":"七言律诗","c":["遥忆当年学立身，兢兢常恐暂埃尘。","孤风自许追千古，特操何曾让一人。","因病简编寻旷弛，离群践履转逡巡。","中宵忽感平生志，回首空过七十春。"]},{"t":"与学者戴舆","f":"七言律诗","c":["茕茕失怙未能言，鞠育劬劳仰母怜。","稍及成童知择善，才邻弱冠已忘眠。","镜当尘积光难缉，车向途艰势易颠。","从此更敦千古志，躬行心得好拳拳。"]},{"t":"自叹","f":"七言绝句","c":["少年不学浪悠悠，老大无成空隐忧。","寄语青春强健客，及时黄卷好埋头。"]},{"t":"寄李子俨","f":"七言绝句","c":["杨柳城头乱絮飞，慇勤客舍再逢时。","山中有约遂何日，羁思悠悠谩寄诗。"]},{"t":"感怀","f":"七言绝句","c":["静把平生一细思，可堪桃李不胜吹。","何能挽得千溪水，净洗灵台一片私。"]},{"t":"龙窟渡拜先曾祖楚江先生墓","f":"七言绝句","c":["青山远入避红尘，遗魄千秋此水滨。","荒陇凄凉重拜日，细从诸老问前因。"]},{"t":"迁居小陂","f":"七言绝句","c":["小陂桥畔记吾庐，七载经营今陟居。","一片灵台无别想，孜孜惟是圣人书。"]},{"t":"夜坐","f":"七言绝句","c":["古道寥寥不易寻，秋风杨柳感人深。","虚堂寂静无言处，黄卷青灯求夜心。"]},{"t":"冬夜怀古 其一","f":"七言绝句","c":["二帝三王隆至治，皋夔周召和应同。","斯人何幸生斯世，一体君民瑞气中。"]},{"t":"冬夜怀古 其二","f":"七言绝句","c":["孔孟孳孳论要道，颜曾公万实同心。","满门师友更酬酢，此乐当时知几深。"]},{"t":"冬夜怀古 其三","f":"七言绝句","c":["濂洛关闽道中兴，游杨黄辅一时生。","大明日月当中丽，多少祥云与景星。"]},{"t":"昼寝觉作","f":"七言绝句","c":["病思昏昏午梦还，熟思历试鼻应酸。","欲知松柏孤高处，须向隆冬雪后看。"]},{"t":"怀孔御史 其一","f":"七言绝句","c":["曾向严亲旧稿中，睹君尺牍语舂容。","知予大过深增惧，几度相思细省躬。"]},{"t":"怀孔御史 其二","f":"七言绝句","c":["几度相思细省躬，可堪名胜耻无穷。","欲求实胜何由得，黄卷须加百倍功。"]},{"t":"晨坐东斋","f":"五言律诗","c":["寂养资良宵，清晨趣应好。","芳露盈华园，碧岚霭春阜。","虚斋独危冠，晴光烂窗牖。","一玩谦亨辞，冷然涤心垢。"]},{"t":"閒兴","f":"五言律诗","c":["贫居日寡营，动息得自眕。","时课诸生馀，还共儿童哂。","出门望旧山，缘篱探新笋。","归坐夕风清，闲情寄瑶轸。"]},{"t":"次学者韵","f":"五言律诗","c":["欲说男儿事，奇功未易收。","灵台须静养，物理贵精求。","岁月忽向晚，关山阻且脩。","分阴宜痛惜，驱策莫迟留。"]},{"t":"暇日偶成","f":"七言绝句","c":["寸心如水淡无波，四体安舒一气和。","有客到斋终日话，怀开应喜善人多。"]},{"t":"病中枕上作 其一","f":"七言绝句","c":["一念之微须致精，公私王霸要分明。","毫埃丝垢宜揩尽，刚立成心大路行。"]},{"t":"病中枕上作 其二","f":"七言绝句","c":["纤私涤尽未为难，要识时中是孔颜。","此个路头何处问，苦心空使鬓毛斑。"]},{"t":"病中枕上作 其三","f":"七言绝句","c":["律身须礼不容疏，公以治心其庶乎。","二者没身而已矣，不知人世有荣枯。"]},{"t":"新居即事","f":"五言律诗","c":["幽赏平生志，安居此庶几。","青山环远近，碧水带东西。","接舍惟樵径，连云只稻畦。","遗经閒恣阅，心迹总高栖。"]},{"t":"改过","f":"七言绝句","c":["四十应当成德时，中心何更有他岐。","其终也已宜深察，剔拔毋令利暂縻。"]},{"t":"即事","f":"七言绝句","c":["养病私欣得自由，日长卧看鲁春秋。","悠然咏到忘言处，一枕清凉午梦幽。"]},{"t":"省己","f":"七言绝句","c":["此心一失栽培力，几向穷途不自持。","静里反躬深省处，风霜却是进脩资。"]},{"t":"处困","f":"七言绝句","c":["遇着艰难须用心，毋令放下便沦沉。","此关若得千里透，信有人间百鍊金。"]},{"t":"寄曰让祈门训导","f":"七言律诗","c":["优游新趣佳山水，仰止前谟近圣贤。","六籍日须鞭策进，寸心幸莫利名牵。","杏坛铎晓光风满，蕙帐琴寒霁月悬。","从古男儿当自奋，剩将事业答青年。"]},{"t":"冬夜步月怀刘悦学先生","f":"七言绝句","c":["读罢閒吟缓出庭，月华如昼院澄澄。","恍思玩易京师夜，曾向吾师学看星。"]},{"t":"枕上偶成","f":"七言绝句","c":["为学如登万仞山，层崖须用小心攀。","前头尽有无穷趣，只是工夫不断难。"]},{"t":"冬至夜枕上作","f":"七言律诗","c":["深造工夫靡敢悭，近来又透一重关。","心思只在圣贤上，梦寐不离文字间。","斯道极知颠倒易，一身痛惜把持难。","微吟又是阳生后，细省迷途驾速还。"]},{"t":"昼寝觉作","f":"七言绝句","c":["渺然方寸经纶本，万感谁怜此地危。","欹枕细思敦艮旨，几人曾向吉中归。"]},{"t":"寄罗秀才","f":"七言律诗","c":["衰谢无才甘陆沉，何烦青眼特遥临。","驩欣便若平生好，慷慨深投半百心。","莫逆尚期清夜话，有怀先寄白头吟。","卜居愿与嘉谋恊，早向春风听好音。"]},{"t":"中堂即事","f":"七言绝句","c":["灯明几净室清幽，满眼图书托士流。","涤砚闲书新得趣，廓然泰宇澹何忧。"]},{"t":"除夕","f":"七言绝句","c":["拥罢寒炉小酌馀，挑灯又近古人书。","一枝粗定身多幸，此地应逢两岁除。"]},{"t":"元日纪梦","f":"七言绝句","c":["为学平生慕至真，孜孜明德与新民。","朝来枕上添新喜，梦里犹深激劝人。"]},{"t":"夜读","f":"七言绝句","c":["疾风吹雨霰交飞，独拨寒炉夜半时。","喜得诸生清苦共，小窗之外尚吾伊。"]},{"t":"诵晦庵诗次韵","f":"五言律诗","c":["诛茅遂幽独，惬此林壑清。","太和酿群卉，天香满衣缨。","病躯无馀事，先人富遗经。","自陪二三子，明窗共经营。"]},{"t":"待月西斋","f":"七言绝句","c":["远爱云山近竹林，芸编堆里更瑶琴。","时行时止凭谁说，待月西斋自养心。"]},{"t":"晓枕作","f":"古风","c":["少年意气凌秋霜，直欲追古豪杰参翱翔。","老去何知万事旷，空令感激增悲伤。","呜呼古人及之良不易，后生慎勿轻流光。"]},{"t":"温楚歌","f":"七言绝句","c":["上国曾传此调清，经年多故忘当丁。","虚堂永昼重温处，吟到多情是故声。"]},{"t":"门外閒坐","f":"七言绝句","c":["习静生憎损病心，晚凉门外独横琴。","呼童细剔溪头树，为爱青青云际岑。"]},{"t":"独步偶成","f":"七言绝句","c":["暂出孤村纵野踪，晚凉归咏更从容。","盈眸好景新晴后，人在乾坤清气中。"]},{"t":"题唐山书阁","f":"七言律诗","c":["流俗滔滔利是趋，居家高阁独储书。","绝韦远绍前人绪，丽泽频来长者车。","香雨芸窗春杳杳，清风兰砌日舒舒。","小陂茅屋应相近，时喜诸郎问鲁鱼。"]},{"t":"私","f":"五言绝句","c":["一念私才起，风波势便增。","若非鏖战勇，方寸几时平。"]},{"t":"分","f":"五言绝句","c":["万事须由命，劳苦徒丧廉。","若非安得分，尽快未能恬。"]},{"t":"名利","f":"七言绝句","c":["眼前名利日纷纭，扰扰何由得性真。","置却身心贫富外，始知世有出尘人。"]},{"t":"苦热观晦庵诗集","f":"七言绝句","c":["炎热侵陵梦少安，茅檐无地可盘桓。","绝胜黄卷多冰雪，朗诵令人骨髓寒。"]},{"t":"读罢枕上喜而有作","f":"七言绝句","c":["读书进处心私幸，更把精灵祷上天。","愿假数年无病困，尚当努力继前贤。"]},{"t":"枕上默诵中庸稍悟一书大旨喜而赋此","f":"七言绝句","c":["句习章燖几十年，其于统会每茫然。","一朝似得优游力，击节深叹圣嗣贤。"]},{"t":"至日感怀","f":"五言律诗","c":["屡醒长更梦，频添暮景愁。","盛时刚易失，多病苦难瘳。","长困荆榛境，终非鸾凤俦。","徘徊当令节，休复慨前脩。"]},{"t":"临流瞑目坐","f":"五言绝句","c":["物外元无我，閒中别有天。","临流时抱膝，此意向谁言。"]},{"t":"寄叶郎中","f":"七言律诗","c":["洁居万事愧吾徒，十载猖狂一薄夫。","贫病不胜书课减，怠荒常是力行疏。","愁来无地堪容足，老去何时可复初。","忽辱高明千里念，题诗遥望独长吁。"]},{"t":"枕上作","f":"五言绝句","c":["仁者无怨尤，节士多饥寒。","至理无定在，君子随时难。"]},{"t":"连珠求药归道中作","f":"七言绝句","c":["问药归来出白云，轻身随处玩馀春。","会心偶记前贤咏，得自由时莫厌贫。"]},{"t":"怀旧","f":"七言律诗","c":["意曾弥月寓东坪，童冠相亲八九朋。","月色满帘天似水，书声彻晓院如冰。","贤关总拟争先入，尘鞅何期竟久萦。","愧我只今空白发，不堪回首负平生。"]},{"t":"夜牧","f":"七言绝句","c":["凉气萧萧露满衣，碧天如洗月如规。","浩歌一曲孤村寂，绿树阴中牧犊归。"]},{"t":"讲罢偶成","f":"七言绝句","c":["万事应须任所遭，胼胝农圃敢辞劳。","西斋讲罢心如水，又对凉天霁月高。"]},{"t":"东窗偶成","f":"七言绝句","c":["虚窗寂寂隔红尘，踪迹虽贫乐甚真。","法帖谩陶閒里趣，高眠时养病中神。"]},{"t":"灌禾","f":"七言绝句","c":["田头一一荷锄过，自放寒流灌晚禾。","随分不辞筋力苦，坐看明月好怀多。"]},{"t":"东斋读晦庵先生诗次韵","f":"七言律诗","c":["朝朝黄卷自埋头，物外从教春复秋。","座接好山青绕屋，门迎活水绿平沟。","旧花匝径红如织，新竹成林翠欲流。","课罢几回閒徙倚，谁怜心赏十分幽。"]},{"t":"赠山中人","f":"七言绝句","c":["徐步春山日未晡，石桥流水竹扶疏。","为求桑柘乘时种，一一烦君手自锄。"]},{"t":"游山","f":"七言律诗","c":["东风新霁好怀多，又复携琴访薜萝。","幽赏正宜穷窈窕，遐观时喜陟嵯峨。","寸心好共寒流淡，一气应同淑景和。","迤逦不妨归步晚，暖烟凉月助吟哦。"]},{"t":"游山","f":"七言律诗","c":["丽景寻幽日日宜，杳然身世在皇羲。","芳林剩馥徐行际，凉石浓阴小憩时。","胜地到来心自醉，吉人逢处话忘疲。","夜深更酹家山月，不惮烟村归去迟。"]},{"t":"题桐冈茅屋","f":"七言律诗","c":["远却嚣尘制芰衣，野塘安处憺忘归。","良畴佳圃怡朝夕，白水青山省是非。","醉里乾坤类箕颍，閒中今古在皇羲。","人生肥遁如斯足，多少功名与愿违。"]},{"t":"病中倦卧偶思年二十四时寓居东坪与诸生夜读赋玩月诗微吟一过神思洒然遂次旧韵","f":"七言律诗","c":["旧吟诵罢病魂清，犹幸灵台一点明。","锻鍊虽然愧金锡，战兢不敢步渊冰。","未容馀日甘衰朽，尚拟诸生更老成。","世泽依然诗礼在，好将尘虑静中澄。"]},{"t":"懒吟","f":"七言绝句","c":["时止时行学养疴，人心天气共融和。","好怀却怕诗拘束，不似前时苦思多。"]},{"t":"同士当度横琴岭","f":"七言绝句","c":["仄径依微落照残，行临绝岭暂怡颜。","他年记得耽幽处，烟树参差远近山。"]},{"t":"寄士当","f":"七言律诗","c":["两地相思渴一逢，忽从华里共春风。","通家不减平生好，指掌深论别后功。","翠岭遥承扶疾送，狂言多谢放怀容。","人事相应从渐省，好伸前约向中庸。"]},{"t":"同孙脩撰曰恭赋诗留石源黄宅","f":"五言绝句","c":["野径联镳日，山楼对榻时。","素心同似水，清兴各留诗。"]},{"t":"赠曰恭","f":"五言律诗","c":["大地收新雨，春山张旧容。","高人淹信宿，佳兴共和风。","丽泽资方好，离歌唱却慵。","更怀贤叔氏，何日定重逢。"]},{"t":"题友琴轩","f":"七言律诗","c":["欲将心事托云和，高辟幽轩远绮罗。","好景洽来人似醉，纤私绝处海无波。","天高地迥云烟散，电掣雷轰风雨多。","我亦平生耽此趣，把君诗卷重摩挲。"]},{"t":"宿黄徵君馆","f":"五言律诗","c":["负炎困行迈，息肩称幽怀。","嚣尘自兹隔，好景从天来。","林静风荏苒，池清月徘徊。","细交知己谈，佳兴何悠哉。"]},{"t":"题北溪松隐","f":"七言律诗","c":["县北溪头松几株，婆娑长荫隐君居。","绿阴寂寂閒吟处，清籁悠悠醉梦馀。","老干冰霜饶冻裂，盘根雨露饱沾濡。","不知桃李春风态，得拟高标万一欤。"]},{"t":"赠宗人士彰","f":"七言律诗","c":["笋舆遥辱到清溪，霜鬓俱怜识面迟。","绿酒细论宗族谊，青灯频析古今疑。","光先事业根须厚，为已功夫志莫移。","别后分阴勤爱惜，重逢未卜是何时。"]},{"t":"题南园","f":"七言律诗","c":["尘世谁无数亩园，个中清致几人怜。","石桥近接云烟墅，苔径旁通薜荔泉。","灵药嘉蔬纷绕舍，碧桃红杏烂遮天。","幅巾方杖逍遥处，世与羲轩共杳然。"]},{"t":"题双贞堂","f":"七言律诗","c":["孀居重见古今悲，一室双贞天下奇。","粹玉精金同姓字，霜松雪竹表心期。","高踪合继前贤传，懿范宜为后辈师。","多少高谈仁义者，几人无愧柏舟辞。"]},{"t":"题大和堂","f":"七言律诗","c":["天人一理费形容，须向三关透后通。","一气坱然穹壤塞，四时顺布古今同。","絪缊总是吾心妙，保合应须日用功。","琴到无弦何所道，始知君子只中庸。"]},{"t":"题听松轩","f":"七言律诗","c":["曾向高轩共好音，乾坤浩荡境沉沉。","恍然指下迷宫羽，不信人间有古今。","瀑涧夜寒鸣雨歇，风林昼静落花深。","回看胜事已成梦，难写凄凉一片心。"]},{"t":"题竹所","f":"七言律诗","c":["富买江干脩竹林，洞门苔径蔚沉沉。","略无尘土杂幽梦，时有天风来好音。","千亩秋霜君子操，万竿春雨化工心。","笋舆未得乘佳兴，漫向良朋寄短吟。"]},{"t":"题翕乐堂","f":"七言律诗","c":["宜家信是顺亲方，归有馀师好细详。","道要何曾离咫尺，事几应不过平常。","埙篪并入春风软，花萼长和化雨香。","至德苟能躬不怠，满门和气自多祥。"]},{"t":"题琴室","f":"七言律诗","c":["一室何妨似斗宽，中含太古兴瀰漫。","春风几席朱丝缓，夜月轩楹玉轸寒。","天耸云峰晴簇簇，花穿香涧暗珊珊。","纤埃不动沉檀细，身世分明在杏坛。"]},{"t":"题野塘新墅","f":"七言律诗","c":["新卜衡茅面野塘，起居长在水云乡。","庭无尘杂心应远，架有图书贫是常。","多种桑麻承雨露，任教冰雪积松篁。","升沉信有平生分，肯学春花逐艳阳。"]},{"t":"宿金石山","f":"七言律诗","c":["间宿仙家陟翠微，石坛旷望本无期。","轻烟杂树新晴后，近水遥山薄暮时。","兴逐高歌春脉脉，心悬往事意迟迟。","素怀欲共何人写，独咏东风月满衣。"]},{"t":"除日奉和族叔父仰学先生见寄诗韵","f":"七言律诗","c":["弱质何堪终日病，不才误染一年尘。","痛惭旧学功焉用，空感春风岁又新。","困鬣正怜鱼圉圉，芳心谁似木欣欣。","题诗远谢吾宗老，总抱冲襟未易伸。"]},{"t":"除夜感怀","f":"七言律诗","c":["虚堂遥夜忆京师，十八题诗尚记之。","二纪光阴何太疾，百年事业竟奚为。","良时孤负追宁及，多病侵陵悔已迟。","从此残魂须爱惜，闲人闲话不相宜。"]},{"t":"元日即事","f":"七言律诗","c":["初晴天气极清妍，况复琴书共晏然。","心静自应春似海，身閒转觉日如年。","亲宾漫得诸生应，疾病多便白昼眠。","准拟花阴分半榻，无怀世上玩先天。"]},{"t":"题云涧幽居","f":"七言律诗","c":["一带寒流浸白云，千林红叶访徵君。","小桥乱匝青霄竹，古屋多熏旧日芸。","细语温淳兼对酒，素琴冲淡更论文。","欲寻后会无由得，漫喜诸郎继典坟。"]},{"t":"寒夜","f":"七言绝句","c":["朔风雨霰夜漫漫，病骨偏惊败絮寒。","应有贱贫寒胜我，斯人谁道一般看。"]},{"t":"寓宝应寺 其一","f":"五言律诗","c":["昼梦无人搅，春窗一味幽。","芳心怜露草，清韵爱晴鸠。","踪迹何须泥，琴书且暂留。","微吟时出院，随意弄寒流。"]},{"t":"寓宝应寺 其二","f":"五言律诗","c":["古塔多高兴，重临又几年。","云烟清晓际，花柳仲春天。","病眼得无恙，尘襟已旷然。","题诗人欲去，好鸟正蹁跹。"]},{"t":"出城道中","f":"五言律诗","c":["行色一身轻，春山鸟乱鸣。","好怀人共赋，佳兴自能乘。","花坞官桥晓，云林牧里清。","素心无物我，取次话平生。"]},{"t":"放水","f":"七言绝句","c":["秋风淅淅月辉辉，又是田头放水时。","坐倚老梅怡病眼，偶逢佳兴一题诗。"]},{"t":"赠友人","f":"七言律诗","c":["琴书深托绿萝溪，风月何人共品题。","流水旧穿幽径转，乔林新与碧云齐。","一犁春雨儿耕稼，百瓮寒泉自灌畦。","随分无非安稳地，相逢何必问丹梯。"]},{"t":"即事","f":"五言绝句","c":["小春风日佳，意适浑无我。","儿女笑相随，缘山摘霜果。"]},{"t":"怀曾祖楚江先生","f":"七言绝句","c":["先生苦学绍专门，贫贱逾知德义尊。","惟是劫灰堪恨处，不馀一字示诸孙。"]},{"t":"怀曾叔祖脩辅训导先生","f":"七言绝句","c":["先生清苦古人俦，六籍研精仕更优。","愧我痴顽成底事，几回遥感旧弓裘。"]},{"t":"听小女弹琴","f":"七言绝句","c":["幽栖心迹似洪荒，花木阴阴日正长。","读罢又亲窗下枕，薰风一曲午天凉。"]},{"t":"同陈正言登李家山次朱子游山诗韵","f":"七言律诗","c":["静来荣辱淡无惊，却喜閒身去就轻。","心目开明随地好，山川奇胜自天成。","短筇密倚经行稳，磐石徐登发咏清。","却忆携琴曾此憩，尘寰寒暑几回更。"]},{"t":"出游","f":"七言律诗","c":["晴光又值小春天，儿女嬉随度野田。","香稻可人时有赖，红尘隔我利无牵。","平冈暂为寻幽历，细草聊因养病眠。","随处会心皆妙境，乾坤生意总悠然。"]},{"t":"阅旧藁毕偶成","f":"七言绝句","c":["连日频将旧稿披，恍然如梦对当时。","知非已晚嗟何及，空使残魂咏小诗。"]},{"t":"春日","f":"七言律诗","c":["物我悠悠付两忘，莫春天气体平康。","奇花杂映阶篱烂，佳木频分户牖香。","童冠芳盟六七辈，圣贤名教两三行。","呼儿杖策嬉游罢，又复高眠向北窗。"]},{"t":"枕上偶成 其一","f":"七言绝句","c":["尝闻洪范思能睿，只恐邪思乱性真。","能于思处分真妄，便是存心格物人。"]},{"t":"枕上偶成 其二","f":"七言绝句","c":["妄想能除心即清，心清一气自和平。","时行时止非人力，慎勿憧憧役此生。"]},{"t":"偶成","f":"七言绝句","c":["竹树阴阴隔世尘，吾伊声里着斯人。","饥餐渴饮聊随分，信是閒中别有春。"]},{"t":"宿周舍","f":"五言绝句","c":["暮色看山罢，清宵寄此楼。","细思名教旨，衰懒是吾忧。"]},{"t":"宿湖田万氏","f":"七言绝句","c":["数家书屋湖山上，我爱湖山几度游。","下榻又从高阁卧，炎窗风雨似清秋。"]},{"t":"木黄岭","f":"七言绝句","c":["偶从佳地又开颜，久坐凉飙意转閒。","平野旷然清远目，白云深处指闽山。"]},{"t":"宿慈明寺","f":"五言绝句","c":["一宿蔚蓝天，炎襟自洒然。","五更凉梦觉，心赏淡无言。"]},{"t":"寄宗人士彰","f":"七言绝句","c":["客路迢迢拟访君，细论心事慰离群。","新晴无奈归程迫，空向青山望白云。"]},{"t":"山家","f":"七言绝句","c":["老兄扫径遥迎客，令弟焚香好煮茶。","自有一般淳朴处，稻花流水两三家。"]},{"t":"赠陈广文","f":"七言绝句","c":["偶送邻翁语隔溪，遥瞻骑从识儒衣。","九天远达尚书命，野水荒山倍益辉。"]},{"t":"孙氏贤母诗","f":"七言绝句","c":["曾向遗经慨小星，柏舟三叹有馀馨。","高踪百世能同调，不负皇天降此生。"]},{"t":"秋夜感怀","f":"七言绝句","c":["当年曾苦读书心，斯道寥寥强自任。","不谓阨穷兼疾疹，蹉跎空得雪盈簪。"]},{"t":"寒夜枕上作","f":"五言律诗","c":["屋弊风如箭，衾单人似冰。","但怜妻子病，敢计此身宁。","夙志空怀古，迂谋拙理生。","体羸何所作，漫喜此心平。"]},{"t":"枕上绝句","f":"五言绝句","c":["风雪无眠夜，泠然细省躬。","此心诚易失，物理倍难穷。"]},{"t":"小年夜","f":"七言绝句","c":["虚堂明烛小年时，子弄瑶琴父咏诗。","会得心中无事旨，乐夫天命复奚疑。"]},{"t":"溪畔偶成","f":"七言绝句","c":["偶来溪畔爱阳坡，瞑坐光风养太和。","幸托林泉交物少，故于情性得功多。"]},{"t":"长塘道中","f":"七言绝句","c":["讲罢归来日向沉，嫩凉徐步爱轻阴。","芳林秀町盈眸好，谁识乾坤造化心。"]},{"t":"月夜","f":"五言绝句","c":["月色秋边白，人心夜半平。","一尘元不滓，高枕玩虚明。"]},{"t":"璿庆夜读喜而赋此勉焉","f":"五言绝句","c":["八岁知勤学，焚膏过二更。","圣功从此始，道只在人弘。"]},{"t":"中夜偶成","f":"七言绝句","c":["病枕醒来镇不眠，起看星象听鸣泉。","寸心敛处能容物，始识天君本泰然。"]},{"t":"挽梁节","f":"七言律诗","c":["颍水翱翔迈等俦，亭亭丹桂倚高秋。","姓名未达黄金阙，梦寐俄惊白玉楼。","堂上幸仍新滫瀡，庭前堪付旧弓裘。","盈虚消息何须计，没有清芬是乃休。"]},{"t":"梦戴时雨训导","f":"七言绝句","c":["记得当年听说诗，客窗几度解人颐。","清风久矣隔今古，又向良宵一梦之。"]},{"t":"怀族叔父仲学先生","f":"七言律诗","c":["忆昨相论古市傍，我才逾冠叔方强。","圣贤事业心皆醉，问学工夫日共忙。","信是中行难体会，也应夙志易荒唐。","秋窗卧病思君处，空愧萧萧两鬓霜。"]},{"t":"莲塘","f":"五言绝句","c":["莲没不知年，塘称尚如昔。","念我名不称，长生谅何益。"]},{"t":"何家山","f":"五言绝句","c":["脩竹淩青冥，乔林郁苍翠。","三世托吾庐，嬉游十经岁。"]},{"t":"坑里","f":"五言绝句","c":["青松夹广路，绿水连芳塘。","茅屋八九家，风俗如虞唐。"]},{"t":"南坑","f":"五言绝句","c":["田宜晚粒香，池济秋阳曝。","南坑专此嘉，吾人竟何谷。"]},{"t":"南冈","f":"五言绝句","c":["忆年童稚时，逐侣于兹牧。","赓歌忘渴饥，皞皞驱归犊。"]},{"t":"对门山","f":"五言绝句","c":["土鼓供儿戏，林泉多珍味。","风物自依然，流光换人世。"]},{"t":"下廒山","f":"五言绝句","c":["为童多此游，负薪给吾爨。","几度江湖上，青山梦中看。"]},{"t":"于家陂","f":"五言绝句","c":["儿童随伯氏，渔此供宾庖。","江湖四十载，往迹惟神交。"]},{"t":"陀上","f":"五言绝句","c":["迢迢陀上路，东去通康庄。","当年断肠别，观者同彷徨。"]},{"t":"承临川县侯李降临弊庐赐以高邮米麻姑酒喜与邻里乡党共分其惠因成此句","f":"七言绝句","c":["泥尊满贮旴江绿，玉粒遥传淮甸香。","白屋荣沾花县赐，喜从乡党一分尝。"]},{"t":"留赠湖田万氏 其一","f":"七言绝句","c":["病违佳约卧柴荆，虚辱衣冠事远迎。","绿酒喜陪今夕话，又将迂阔渎高听。"]},{"t":"留赠湖田万氏 其二","f":"七言绝句","c":["朝来听取别时歌，善恶由来不共科。","欲向事几明摆析，工夫不厌读书多。"]},{"t":"赠故里亲友","f":"七言绝句","c":["跋涉西还访旧居，故人心绪总何如。","平生拙学无他技，到处逢人劝读书。"]},{"t":"题柏堂","f":"七言律诗","c":["灵根亲傍陇头安，翠盖凌空已郁盘。","岁月岂胜和泪数，风霜几向断肠看。","苦心循是天真易，峻节当兹末俗难。","珍重贤郎能不匮，高堂特笔障狂澜。"]},{"t":"奉谢诸乡邻","f":"七言律诗","c":["草堂遥复种湖滨，此地相将二百春。","出处无能惭德义，往来盛礼谢乡邻。","从今厚俗虽交善，自古为居必择仁。","海内喜瞻声教远，时雍共作太平民。"]},{"t":"小年夜绝句","f":"七言绝句","c":["煌煌银烛照良宵，乐此升平荷圣朝。","门户恍思前甲子，肃然世泽感迢遥。"]},{"t":"除日","f":"七言绝句","c":["此地栖迟忽岁除，萍踪如梦对琴书。","宗门一一经过处，共喜云孙复故居。"]},{"t":"除夜","f":"七言绝句","c":["妻子团栾身少瘥，故居风景庆时和。","老年襟抱无他感，但恨读书功不多。"]},{"t":"寄谢杨宪副赠周礼注疏","f":"七言绝句","c":["梦寐周公制作心，遗编厚贶辱遥临。","焚香拜罢时开卷，感激于君定几深。"]},{"t":"题太古轩","f":"七言绝句","c":["轩前化日正迟迟，轩里幽人自得时。","一曲云和春万顷，杳然身世在皇羲。"]},{"t":"种湖","f":"七言绝句","c":["湖久难稽得种名，乡邻聊共古今称。","我来几度游湖畔，何限徘徊异世情。"]},{"t":"大桥","f":"七言绝句","c":["乡里流传小小孤，众流挟束帖如无。","伊人何自卑其局，试问为仁安属乎。"]},{"t":"何陂","f":"七言绝句","c":["万顷汪洋浸白云，潜滋暗助发生仁。","试于翘望云霓处，始见深功信有神。"]},{"t":"江家山","f":"七言绝句","c":["清眺长便山外山，层峦叠嶂巧回环。","个中自有无穷趣，不惜芒鞋数往还。"]},{"t":"城上松","f":"七言绝句","c":["隐隐东南几万松，翠华如涌四时同。","高标独傲冰霜表，生意都归雨露中。"]},{"t":"读春秋","f":"七言绝句","c":["世情诗思两悠悠，老去何心复梦周。","风雨午窗春睡起，间将吾志向春秋。"]},{"t":"自讼","f":"七言绝句","c":["徒尔昂藏生世间，可怜此志久希颜。","如何白发龙钟际，依旧身心就检难。"]},{"t":"约","f":"七言绝句","c":["为恶都缘自放多，私根随处费消磨。","从今要术须归约，履薄临深养太和。"]},{"t":"陆大参赐胙","f":"七言绝句","c":["画省颁膰到荜门，极知雅意笃斯文。","独惭浅薄将焉称，细与乡邻族党论。"]},{"t":"题石宪使慈寿堂","f":"七言律诗","c":["西山淑气蔼蓬莱，华馆春风寿域开。","信是深功由我积，固应馀庆自天来。","兰阶綵绣荣南服，锦巷珠玑应上台。","疏薄岂胜膺授简，日同黎庶仰崇台。"]},{"t":"赠王太守荣满","f":"五言绝句","c":["皂盖朝天日，黎民卧辙时。","重临俱有望，竹马候归期。"]},{"t":"示儿","f":"七言绝句","c":["青灯父子话从容，贫贱逾知乐意浓。","从此莫忘慈教旨，诗书宜早用深功。"]},{"t":"丰安道中","f":"七言绝句","c":["宿雨初收淑气回，春山归兴正悠哉。","云烟处处依微敛，桃李家家自在开。"]},{"t":"即事","f":"七言绝句","c":["养拙柴门日久沉，子勤习诵父哦吟。","始知陋巷箪瓢乐，千载同符只此心。"]},{"t":"奉寄家兄","f":"七言绝句","c":["独居迢递忆吾兄，犹记当年童稚情。","万事相看俱潦倒，流光如梦迹如萍。"]},{"t":"寄胡子贞","f":"七言绝句","c":["谬为何自可成章，半百年华感兴长。","惆怅故人头总白，青山归梦绕莲塘。"]},{"t":"昼寝偶成","f":"五言绝句","c":["老境日向逼，学业靡所成。","空想古英哲，怅然念平生。"]},{"t":"子贞及一舍弟送归途中口号","f":"七言绝句","c":["久客欣逢故里游，山中风景值清秋。","怡怡切切偲偲处，指点归途去复休。"]},{"t":"宿湖头","f":"五言绝句","c":["野境云俱暝，江空雨未休。","问程频策马，灯火宿湖头。"]},{"t":"重游瓜石感怀","f":"七言绝句","c":["偶尔驱驰此地过，故人消息近如何。","短筇白发遥相迓，暗忆流年一掷梭。"]},{"t":"夜宿胡氏梅竹轩九韶季恒在焉","f":"五言律诗","c":["梅竹幽栖处，良朋偶盍簪。","留连清夜饮，俛仰莫年心。","明日又南北，转头成古今。","平生江海梦，偏向旧游深。"]},{"t":"望家山感怀","f":"七言绝句","c":["望望家山近故丘，西风疋马怅高秋。","旧游历历人如梦，昨日少年今白头。"]},{"t":"追和刘秀野诗韵 其一","f":"五言律诗","c":["十载劳经营，得卜寒泉麓。","虽乏囊中资，幸安一茅屋。","桃李君自花，风月吾人独。","侨居非素心，言归事耕读。"]},{"t":"追和刘秀野诗韵 其二","f":"五言律诗","c":["我居清溪曲，绕屋罗青山。","白云自来往，脩竹无柴关。","翘企古人躅，逸驾容追攀。","悠然一瓢饮，不知有尘寰。"]},{"t":"追和刘秀野诗韵 其三","f":"五言律诗","c":["莫春春服成，嬉游吾所爱。","至哉浴沂心，斯言不下带。","浩荡六合间，彻视宁有碍。","何事千载馀，兹境稀能会。"]},{"t":"追和刘秀野诗韵 其四","f":"五言律诗","c":["夙昔闻太华，耸拔何其尊。","未遑游汗漫，流传少陵君。","群峰无远近，环立皆儿孙。","何当脱尘鞅，胜览跻青云。"]},{"t":"追和刘秀野诗韵 其五","f":"五言律诗","c":["樗散竟奚为，无禽怜旧井。","夙志成蹉跎，星流百年景。","俯仰起遐思，空嗟圣途永。","闭关事微阳，残魂此其幸。"]},{"t":"追和刘秀野诗韵 其六","f":"五言律诗","c":["我思君子为，洪钧岂小补。","化日舒以长，仁风被寰宇。","下视驩娱如，区区焉足数。","安得千载人，谁知此心苦。"]},{"t":"追和刘秀野诗韵 其七","f":"古风","c":["王者大如何，乾元物资始。","亭?一何心，家家自桃李。","固不令人怒，亦不令人喜。","帝力何有哉，皞皞皆仁里。"]},{"t":"追和刘秀野诗韵 其八","f":"五言律诗","c":["素心在丘壑，衡茅隐松萝。","时访李邺侯，或亲郭橐驼。","空谷响樵唱，绿野喧农歌。","暝然日之夕，不乐复如何。"]},{"t":"追和刘秀野诗韵 其九","f":"五言律诗","c":["恭默观我生，兢兢虞逐物。","立志在有为，固当有所不。","图史娱朝昏，云霞媚岩窟。","吾道卜终焉，何心于象笏。"]},{"t":"追和刘秀野诗韵 其十","f":"五言律诗","c":["人生何所贵，贵在为丈夫。","古今表表者，脂韦岂良图。","风霜竹凌厉，冰雪梅清癯。","壮志一少懈，焉足为有无。"]},{"t":"宿楼府庵中 其一","f":"七言绝句","c":["客路忻同胜友行，贪看山水一身轻。","幽栖远就云林宿，明月清风万古情。"]},{"t":"宿楼府庵中 其二","f":"七言绝句","c":["歇马高林见水源，时从明月咏潺湲。","不知浩荡沧溟上，万折东趋路几千。"]},{"t":"宿格山禅林寺","f":"五言绝句","c":["骑从劳英友，秋山共客游。","禅窗无寐处，竹月涌寒流。"]},{"t":"途中偶成","f":"七言绝句","c":["日斜马滑惊危石，路暗人疲怯败桥。","雷电屡防风雨至，须臾明月露青霄。"]},{"t":"奉寄黄泰庄先辈","f":"五言绝句","c":["惆怅白头吟，云山契阔深。","何当重剪烛，细叙百年心。"]},{"t":"秋夜","f":"五言绝句","c":["清觉当凉夜，灵台正静虚。","寒光皎残月，星象烂联珠。"]},{"t":"柬黄季恒","f":"七言绝句","c":["连日青山共好怀，胜游清话两悠哉。","诗筒又促乘流约，佳骑明朝来未来。"]},{"t":"舟次打石港感怀","f":"七言绝句","c":["不出门庭十五年，旧游遥历重凄然。","昂藏徒有平生志，容易因循雪满颠。"]},{"t":"璿庆同余李友登陆游憩","f":"七言绝句","c":["童冠相呼六七朋，晴沙迤逦并舟行。","个中真意人谁会，慨想当年与点情。"]},{"t":"独坐偶成","f":"七言绝句","c":["曝背墙头独咏诗，风帆远近鸟差池。","江干举目皆真乐，底事人心苦自私。"]},{"t":"发桂家林","f":"七言绝句","c":["故人迎候暂维舟，行李匆匆去莫留。","白首相逢多病后，西风斜日两绸缪。"]},{"t":"宿池港","f":"七言绝句","c":["卧病衡茅久自私，懒心只与白云宜。","那知风雨江湖夜，恍似平生涉历时。"]},{"t":"蓬漏不堪坐起赋此以慰余李诸友","f":"七言绝句","c":["风雨疏蓬共不眠，可怜此志在希贤。","谁能万一朱夫子，林范何劳远接联。"]},{"t":"次桃树港与璿庆登岸閒眺","f":"七言绝句","c":["忆昨儿童随伯氏，趋庭曾此系扁舟。","重来俯仰悲华发，碌碌空过四十秋。"]},{"t":"宿板溪 其一","f":"七言绝句","c":["离却蓬窗宿此溪，青灯华屋又吾伊。","芳筵倦酌辞清醑，随意閒裁听雨诗。"]},{"t":"宿板溪 其二","f":"七言绝句","c":["诗罢吾伊尚未停，拥炉更喜共残灯。","工夫似此能无间，何患当年艺不成。"]},{"t":"宿板溪 其三","f":"七言绝句","c":["跋涉长途未觉疲，晦明不必问前期。","寸心始觉元无外，万事须知各有宜。"]},{"t":"辞李氏宴","f":"七言绝句","c":["特感华筵美意深，不才自分实难任。","平生非欲多违忤，恐负区区雅素心。"]},{"t":"道中见梅","f":"七言绝句","c":["虬枝忽见雪交加，自在芳心阅岁华。","客里但贪春意好，短墙不必问谁家。"]},{"t":"望豫章城怀胡祭酒先生","f":"七言绝句","c":["行行渐近豫章城，烟树微茫两眼青。","野水平桥时独立，肃然起敬为先生。"]},{"t":"璿庆失金","f":"七言绝句","c":["人亡人得不须怜，佩服嘉谟亦有年。","今日失金何足较，自当观理学前贤。"]},{"t":"宿悬榻里有怀往事","f":"七言绝句","c":["尘世悠悠几古今，偶投仁里一沉吟。","山川孕秀知多少，何事先生得独深。"]},{"t":"拜胡祭酒先生","f":"七言绝句","c":["一拜膺门百感并，归来犹自怅平生。","客窗展转难成寐，风雨萧萧永夜心。"]},{"t":"留题伍氏馆","f":"七言律诗","c":["琴书信宿托高轩，细接襟期意豁然。","堂上埙篪春似海，阶前梧竹碧参天。","江山映带供真趣，田圃萦环庆有年。","不待有心行乐事，自然至乐日无边。"]},{"t":"客夜","f":"七言绝句","c":["苦心遥夜独观生，时听书声杂雨声。","但得晴明游览毕，青山回首数归程。"]},{"t":"喜晴","f":"七言绝句","c":["晨起呼童问晦明，遥天红碧报新晴。","江山豫有登临约，何处凭高一畅情。"]},{"t":"游孺子亭次朱子诗韵","f":"七言绝句","c":["孺子高风固莫寻，紫阳馀韵感人深。","乾坤那得有今古，千载斯人只此心。"]},{"t":"宿豫章城","f":"五言绝句","c":["白发悲心事，青阳逼岁除。","江城回客枕，寒漏四更馀。"]},{"t":"奉次胡祭酒先生诗韵","f":"七言律诗","c":["抠趋百里亲先执，犹是当年老长官。","绛帐春风酣德教，红炉瑞气盛杯盘。","客边病思饥应忘，江上归心岁已残。","拜得新诗缘路读，梅花冰雪为谁寒。"]},{"t":"问舟南浦","f":"七言绝句","c":["客里逢人漫说诗，从教归计尚迟迟。","时将泽国天然趣，指点苍茫一教儿。"]},{"t":"发南浦示璿庆及诸生","f":"七言绝句","c":["细雨斜风竹叶舟，长蓑短笠溯寒流。","呼儿又喜新诗就，丽泽何妨迭倡酬。"]},{"t":"野宿","f":"七言绝句","c":["满江风雨泊孤舟，舴艋能生逆旅愁。","伫立渐看西北好，一天明月乱云收。"]},{"t":"月下行舟","f":"七言绝句","c":["客衾局促难安枕，夜半孤舟带月操。","童仆总知归去好，寒汀鱼贯不辞劳。"]},{"t":"次槎江","f":"七言绝句","c":["半月讴吟多胜赏，太平处处共时雍。","江山又极登临目，图画天开杳霭中。"]},{"t":"次嵩山","f":"七言绝句","c":["长湖东北是嵩山，山下人家面碧湾。","今日竹林清逸处，云和一曲特开颜。"]},{"t":"宿曹溪感兴寺","f":"七言绝句","c":["忙冲暝色度寒汀，驻马禅林月倍清。","东道欲知迎候盛，高歌又益四三生。"]},{"t":"早行马上口占","f":"七言绝句","c":["断续江村踏月行，谁家茅屋乱鸡鸣。","欢呼童仆愁迷道，时听云林远近声。"]},{"t":"次湖莽","f":"七言绝句","c":["胜地久闻蕃俊杰，归鞭今喜到华居。","丁宁笃世无他术，礼义多循饱读书。"]},{"t":"崔氏默庵偶成","f":"七言绝句","c":["旧家文物总诜诜，又喜深衣与幅巾。","晴色满窗春可掬，恍然疑对葛天民。"]},{"t":"喜晴马上口占","f":"七言绝句","c":["客路秪愁风雨恶，马蹄翻得踏晴沙。","轻风拂面春和煦，到处江梅着好花。"]},{"t":"宿潼湖","f":"七言绝句","c":["霜树模糊烟水村，投装游子夜敲门。","久知东道逢迎意，特解诗囊为后昆。"]},{"t":"舟中听诸生歌诗","f":"七言绝句","c":["行李宁家已有期，云帆更喜夜风吹。","诸生各有平安庆，促膝闻歌往复诗。"]},{"t":"赠同行诸生","f":"七言绝句","c":["半月追随谒国宾，今朝分手重慇勤。","还家各记丁宁教，私录工夫日日新。"]},{"t":"次娄家洲","f":"七言绝句","c":["翱翔艺苑少年时，曾听吾伊忘渴饥。","他日橘林洲上馆，华颠惆怅旧题诗。"]},{"t":"听本宗诸生早读","f":"七言绝句","c":["金鸡声乱曙光微，已喜吾伊动隔扉。","自是日新宜若此，漫题诗句助箴规。"]},{"t":"怀孔御史","f":"七言绝句","c":["当年曾辱报亲书，意气深惭过许予。","夜雨空怀人似玉，华颠谁念挂钩鱼。"]},{"t":"奉和族叔父仲学先生","f":"七言律诗","c":["江湖半月忝为宾，浪说文章泣鬼神。","自是秉彝攸好德，谁怜观过却知仁。","倦酣竹叶缘多病，剩赋梅花为好春。","幸免非几全素履，未妨来往作閒人。"]},{"t":"吊先友孙博士先生","f":"七言绝句","c":["忆瞻颜色自儿童，回首官居一梦中。","试问寂寥先友记，玉山多在白云封。"]},{"t":"留凤栖原周氏","f":"七言绝句","c":["中宵凉月添佳兴，际晓晴山净好怀。","但得主人能好客，几时无事又重来。"]},{"t":"以石竹雪竹诸字赠周余诸友","f":"七言绝句","c":["节序明朝岁已除，青衫犹辱访侨居。","预留拙笔聊相赠，点画虽疏意有馀。"]},{"t":"元旦枕上作","f":"七言绝句","c":["升沉荣悴信由天，莫以私心搅自然。","人事尽时须委命，春风随处咏新年。"]},{"t":"奉寄家兄","f":"七言绝句","c":["客里屠苏岁又周，诗成无使怅悠悠。","春风偶得家山雁，漫托乡心达故丘。"]},{"t":"寒夜有怀九韶同不肖奔丧金陵","f":"七言绝句","c":["昨夜寒窗寐不成，荒迷却忆旧游情。","孤舟反侧天涯梦，千里劳君两眼青。"]},{"t":"发新庄渡","f":"七言绝句","c":["云天雨歇乱山青，新绿添江一棹轻。","前后衣冠催上道，春风共作写书行。"]},{"t":"船头与璿庆閒眺","f":"七言绝句","c":["江天冥漠橹咿哑，云树烟村野鸟斜。","船头骥子时同坐，久话令人忘算沙。"]},{"t":"宿万石渡示璿庆及诸生","f":"七言绝句","c":["枉渚平林烟雨昏，一篙春涨泊柴门。","吾伊莫使新功缓，共拟青灯入夜分。"]},{"t":"舟中小立","f":"七言绝句","c":["晴色微开远近山，倚篷閒看鸟回还。","数声柔橹苍茫外，又载吾伊过别湾。"]},{"t":"钟陵城南江畔","f":"七言绝句","c":["江城终日雨如麻，病骨侵陵暖尚赊。","晴色忽惊春似锦，偶从此地看桃花。"]},{"t":"九莲寺即事","f":"七言绝句","c":["竹树深深隔世机，野人心事幸无违。","简编随意閒舒卷，尽日春山独掩扉。"]},{"t":"承大司成先生惠豫章文集抄录已完偶成鄙句","f":"七言绝句","c":["闽学渊源夙所钦，遗编伏读更沉吟。","馀生苟得分毫益，总是先生嘉惠心。"]},{"t":"南浦登舟","f":"七言绝句","c":["漫托城南十日居，禅窗松竹共清癯。","桃花晴涨移归缆，载得新抄几卷书。"]},{"t":"发南浦","f":"七言绝句","c":["杳霭江山远近楼，桃花晴映绿杨洲。","满船尽是青衿客，谁道春风非胜游。"]},{"t":"丰城史郎中宅","f":"七言绝句","c":["桃李春风访郤林，青灯犹记旧时吟。","图书满目人何在，万里凄凉瘴海心。"]},{"t":"宿龙潭","f":"七言绝句","c":["微雨沾鞍风满襟，长途无使客愁侵。","天光云影投装处，流水高山是我心。"]},{"t":"宿吉塘","f":"七言绝句","c":["令弟遥迎自豫章，难兄缘道候行装。","春风共喜新晴好，问水看山到吉塘。"]},{"t":"宿樟镇灵峰寺","f":"七言绝句","c":["遥携稚子访名山，多谢朋游伴往还。","幽意更便良夜宿，光风霁月满禅关。"]},{"t":"别吉塘","f":"七言绝句","c":["数家春树鸟关关，几处青青雨后山。","胜槩倚楼人欲别，诗情多在有无间。"]},{"t":"经天井","f":"五言绝句","c":["晴指家山路，时询天井名。","春风迎马首，投辖二生情。"]},{"t":"重访传秉彝","f":"七言绝句","c":["日明风淡橹柔和，红树村村逐望多。","笑指竹林曾宿处，遥携爱子抱琴过。"]},{"t":"宿沙溪","f":"七言绝句","c":["红叶西风远盍簪，高堂清夜共瑶琴。","长歌不觉诗狂甚，一写平生慷慨心。"]},{"t":"宿龙溪","f":"七言绝句","c":["灯火欢迎不惮劳，夜深舆马度江皋。","虚窗一榻平安梦，人在春风醉碧桃。"]},{"t":"宿金鸡城前","f":"七言绝句","c":["红叶归心刚似飞，相逢尊酒别迟迟。","衣冠淳雅江山胜，到处何妨一赋诗。"]},{"t":"宿五峰","f":"七言绝句","c":["歇鞍遥自客游归，宝篆兰膏处处宜。","促席细聆眉寿话，和风甘雨共忘饥。"]},{"t":"重经彭源","f":"七言绝句","c":["旧德乡邦夙所推，争誇玉叶映金枝。","风流云散客来晚，立马平桥独步迟。"]},{"t":"自赤涧先陇后岭循北原丰稔坑以出偶成绝句","f":"七言绝句","c":["童冠嬉谐归去迟，山风淡淡日斜晖。","登临自惬平生乐，杖策抠衣忘渴饥。"]},{"t":"游东山","f":"七言绝句","c":["贪看形胜不知疲，徐步东山话昔时。","流水高山人已远，尚馀清韵起遐思。"]},{"t":"别湖田","f":"七言绝句","c":["际晓晴开一叶舟，故人高谊共悠悠。","回头却忆沙头别，寒菽模糊烟树稠。"]},{"t":"宿山家","f":"五言绝句","c":["隔岭望丛筠，方塘宿白云。","客心清不寐，弦诵夜深闻。"]},{"t":"云峰寺即事","f":"七言绝句","c":["松竹禅房深复深，云和夜度玉泉音。","泠然共得惺惺法，记取银灯不寐心。"]},{"t":"宿曰让宅","f":"七言绝句","c":["杖策欢迎荷老亲，候门稚子总欣欣。","独怜霁月光风夜，白雪阳春忆远人。"]},{"t":"访杨德全致政归","f":"七言绝句","c":["罢郡归时已白头，杖藜日看橘林洲。","客来若问浮生事，明月清风酒一瓯。"]},{"t":"宿厚郭胡氏","f":"七言律诗","c":["烟外微闻款语声，马前徐问二生名。","回头喜接平生友，拥道难胜盛族情。","绿酒歌酣霜夜月，青灯人在玉壶冰。","巡檐更数高居好，胜水佳山眼倍明。"]},{"t":"留别樟溪王大邦","f":"七言绝句","c":["桑梓连阴三百春，重来谢别访高门。","白头相眷无他属，剩买诗书教子孙。"]},{"t":"宿城南慈慧寺","f":"七言绝句","c":["寻梅问竹绕城南，喜得幽栖寄此龛。","诗罢杳无尘土念，怡然清梦入春酣。"]},{"t":"城南识别","f":"七言绝句","c":["满寺衣冠霁色开，青春华发映蓬莱。","鸿爪雪泥他日梦，江云渭树总悠哉。"]},{"t":"题临江寺","f":"七言绝句","c":["霜蹄轻捷快晴光，古寺时耽野趣长。","乘兴不知沙径永，题诗人在水云乡。"]},{"t":"石井山家","f":"七言绝句","c":["清溪诘屈逗云萝，白屋青烟绿树多。","散马平冈人待爨，閒教稚子度云和。"]},{"t":"梦中题画龙","f":"古风","c":["混辟乾坤，动摇山岳。","雾雨几千年，云雷看一跃。"]},{"t":"冬日拜五六府君墓 其一","f":"七言绝句","c":["断续崇冈野渡傍，朔云寒日共荒凉。","劫灰容易成今古，文献凋零事渺茫。"]},{"t":"冬日拜五六府君墓 其二","f":"七言绝句","c":["郭五名存事已非，断畦荒堑一凄其。","黄成虽有衡茅在，欲问前因总不知。"]},{"t":"奉别族里","f":"七言绝句","c":["旧乡三载赖周旋，归兴朝来已浩然。","莫怪迂疏临别语，人间万事读书先。"]},{"t":"宿栎原","f":"七言绝句","c":["移居又喜入青山，跋涉惟怜仆御难。","风雨冻途蓑笠惫，茅斋烟火暂开颜。"]},{"t":"复居小陂","f":"七言绝句","c":["省墓归来二载馀，青山绿水复相娱。","两乡故旧皆青眼，何处人烟不可居。"]},{"t":"元日感怀","f":"七言绝句","c":["山川依旧岁华新，又见纷纷拜节人。","昨日儿童今皓首，蹉跎羞看故园春。"]},{"t":"偶成","f":"五言律诗","c":["病躯倦长昼，出门俯清湍。","倚筇坐浓樾，支颐不胜冠。","遥峰馀奇观，绤袖长飙寒。","呼儿授新句，孤怀渺云端。"]},{"t":"游罗山","f":"七言绝句","c":["流水溅溅石峭棱，天风袅袅景和平。","慇勤不惜跻攀力，绝岭须教一共登。"]},{"t":"宿石桥宗人家","f":"七言绝句","c":["遥遥西蜀出长垣，奕叶青云几百年。","今日石桥楼阁话，青灯绿酒怅前缘。"]},{"t":"示儿","f":"五言绝句","c":["病多自愈惫，夙志竟成空。","所属惟吾子，云何不着功。"]},{"t":"次任教授见寄诗韵","f":"七言绝句","c":["独怜樗散滥时名，何意珠玑落玉京。","侧喜满城新教化，男儿端不负平生。"]},{"t":"奉寄族里","f":"七言绝句","c":["琴剑南来接孟邻，四桥桑梓托情亲。","三年馆谷春风里，谁道今人乏古人。"]},{"t":"赠别周圻","f":"七言绝句","c":["欲写离情久倦吟，一尊聊向菊花斟。","悬知南北天涯梦，总是平生旧好心。"]},{"t":"次任教授倡义哀赙葬余忠母子诗韵兼挽生焉","f":"七言律诗","c":["泮水横经属老苍，馀波重被困穷丧。","位卑正忆兼山艮，河广俄惊一苇航。","白屋伊威从壁立，浮名蠛蠓任天荒。","我歌漫答仁人利，勉尔遗孤勿太伤。"]},{"t":"除日祀先","f":"七言绝句","c":["病骨支离不自任，强将清酌共儿斟。","恍然今古凄其处，老泪难胜罔极心。"]},{"t":"除夜独坐","f":"七言绝句","c":["久坐寒炉频自拨，倦来岁酒不成斟。","细看万事无能处，空忆平生慷慨心。"]},{"t":"牧归途中作","f":"七言绝句","c":["夕阳归马正从容，出峡时迎入峡风。","无数好峰罗远近，朗吟身在翠屏中。"]},{"t":"赠王九鼎丹成还郡兼柬任郡博","f":"七言绝句","c":["归骑翩翩大药成，野花啼鸟踏新晴。","绣衣时问衡门旧，老鬓萧疏学养生。"]},{"t":"又赠九鼎","f":"七言绝句","c":["离坎功成恊太和，微躯偏幸得春多。","何由广假回生手，遍起群生远近疴。"]},{"t":"雨后神岭晚眺","f":"七言绝句","c":["烟收云敛夕阳残，高下青松远近山。","白鸟自飞人自度，个中真意憺忘还。"]},{"t":"赠邹丘王三生","f":"五言绝句","c":["送送城西道，踟蹰故意深。","一杯西廨酒，聊赠白头吟。"]},{"t":"题牛氏慈侍堂","f":"七言绝句","c":["高堂綵戏寿如山，帘幕春风燕语閒。","今日老莱头复雪，庭前依旧舞斑斓。"]},{"t":"重宿宝应寺彝公房","f":"七言绝句","c":["玩水看山偶独来，西风重历旧楼台。","光阴一纪如旋毂，又听晨钟动老怀。"]},{"t":"留赠胥经历","f":"七言绝句","c":["连矾锦里偶经过，华发青灯叙旧多。","更欲细聆先子梦，何时飞旆碧山阿。"]},{"t":"赠牛升","f":"七言绝句","c":["昨日追寻今又来，好怀端为故人开。","慇勤更有平生念，群从何时访翠崖。"]},{"t":"徐陂道中","f":"七言绝句","c":["作客秋风百里归，重冈歇马步逶迤。","观生恰喜心无事，缓数云峰独咏诗。"]},{"t":"送陈庸从军江浦","f":"七言绝句","c":["慈母新成游子衣，离歌欲唱意迟迟。","四方总是男儿事，忠孝惟应两勖之。"]},{"t":"游西京赤冈故郡遗迹","f":"七言绝句","c":["群峰崒嵂走铜陵，叠嶂蜿蜒落故城。","人去山空年自换，十朝兴废一棋枰。"]},{"t":"同王九鼎省石井先陇","f":"七言绝句","c":["故郡城头话几朝，飘然石井又联镳。","高吟共得清秋兴，斜日不知归路遥。"]},{"t":"九月壬午承王九鼎同省石井先陇罢宿惠民药局丙丁夜虚堂隐几偶思及之因成此句","f":"七言绝句","c":["江山随处倚高秋，一榻时从药局留。","明月满城更向寂，缓携儿子语街头。"]},{"t":"樟溪即事","f":"七言绝句","c":["一上层轩味自凉，虚明更得读书窗。","泠然睡起閒开卷，白雪阳春四五章。"]},{"t":"重宿白杨寺","f":"七言绝句","c":["策马平桥又问禅，萋萋春草月娟娟。","萧然一榻平安梦，夜半溪声落枕边。"]},{"t":"宿旴江郡庠","f":"五言古诗","c":["迢迢去乡井，长途日可畏。","朝辞白杨阪，莫历旴江涘。","一枝失所托，行迈更靡靡。","挹此泮宫宾，倾盖良偶尔。","举觞叙前缘，剪烛开新制。","古人诚我师，匪难固匪易。","诵言曰惟熟，析理尤宜细。","仁哉后获心，正谊宁谋利。","俛焉日孳孳，汨汨川自至。"]},{"t":"自慈明寺东游龙安镇","f":"七言绝句","c":["面面春山涌翠华，湾湾流水涨晴沙。","客怀却喜东游好，高下楼台远近花。"]},{"t":"慈明寺即事","f":"七言绝句","c":["倦客怀归归路难，禅房起坐养衰残。","忽惊青嶂婵娟月，拄颊微吟独倚阑。"]},{"t":"宿南城邑庠","f":"五言绝句","c":["风雨长途倦，归怀日浩然。","息肩芹水上，端为广文贤。"]},{"t":"寄题程氏春风亭","f":"七言绝句","c":["独对寒檠事短吟，有怀偏向故人深。","却因华扁生新感，惆怅春风万古心。"]},{"t":"东窗独坐有怀先友秦庄仲纶","f":"七言绝句","c":["旧游久矣怅晨星，溪上梅花岁又更。","寂寞柴门多病际，平生双眼为谁青。"]},{"t":"拟钱塘怀古 其一","f":"七言绝句","c":["朔漠心旌日夜悬，义旗遥驻此山川。","只疑春物芳菲处，莫是人间别有天。"]},{"t":"拟钱塘怀古 其二","f":"七言绝句","c":["恩隆义重是君亲，忍着南冠一水滨。","顿首无衣谁氏子，卧薪尝胆乃何人。"]},{"t":"题芸阁示小儿璿庆","f":"七言律诗","c":["幽偏特启芸香阁，阁上工夫忙未忙。","从古共忧时易失，前程谁进日无疆。","光风霁月濂溪上，瑞日祥云洛水阳。","户牖盘楹思有戒，拳拳馀意托新章。"]},{"t":"题雪窗示璿庆","f":"五言律诗","c":["笃志宜师古，深功贵自今。","弄丸元是熟，添火戒非钦。","历历圣贤对，昭昭上帝临。","老怀何所祷，细写雪窗吟。"]},{"t":"题立雪斋","f":"七言绝句","c":["总总谁无无极真，可胜师道日沦湮。","民生三事元如一，何讶当年立雪人。"]},{"t":"题樟溪书屋","f":"七言绝句","c":["桑梓阴阴接种湖，湖边心事寄俞都。","风流云散春光莫，几对溪头夜月孤。"]},{"t":"题乌冈别墅","f":"七言律诗","c":["乌冈元与柘冈连，卜得幽栖慨昔贤。","栋宇漫题新岁月，烟霞仍是旧林泉。","高山仰止从吾好，明德惟馨自古然。","勿药会须乘兴去，为君细和武夷篇。"]},{"t":"题耕乐轩","f":"七言绝句","c":["风景依稀似有莘，东皋谷雨满春田。","个中乐事人谁会，日用由来总是天。"]},{"t":"足成梦中绝句","f":"七言绝句","c":["放犊长村月正明，归来暂喜病魂清。","一衾幽梦春风里，又度良宵三四更。"]},{"t":"牧江家坑","f":"七言绝句","c":["残经挂角日来游，邃谷青山处处幽。","积雨草肥黄犊饱，吾伊声里一晴鸠。"]},{"t":"江家坑偶成","f":"七言绝句","c":["群芳深处绿阴凉，童冠相呼受讲忙。","又与山灵添故事，曾从此地说匡章。"]},{"t":"游山","f":"七言绝句","c":["盘盘樵径入云丛，选胜寻幽到碧空。","不意羽翰生病骨，翩翩归袂又乘风。"]},{"t":"东坑幽谷","f":"七言绝句","c":["崖倾谷转水溅溅，物外乾坤自杳然。","待得岭头幽搆毕，时时来伴白云眠。"]},{"t":"东坑幽谷","f":"五言律诗","c":["东坑有幽谷，邈尔浮云端。","阴林白日静，石溜寒潺潺。","苍苔人迹罕，好鸟时绵蛮。","我游日心醉，閒谣澹忘还。"]},{"t":"大畬冈望抚州城奉怀任潘诸广文及五峰亲旧","f":"七言绝句","c":["亭亭古木转繁阴，拂面清风昼满襟。","坐接水云城郭近，新诗聊为故人吟。"]},{"t":"题潘氏潭江先址","f":"七言绝句","c":["时从官舍梦家乡，先址依稀事渺茫。","欲托孝思知有在，潭江烟雨树苍苍。"]},{"t":"奉寄族叔父仲学先生","f":"七言绝句","c":["游子归时亲倚闾，斑衣华发近何如。","生涯随分田园好，日课诸孙读父书。"]},{"t":"怀晏黎二生","f":"七言绝句","c":["风雨凄其客路赊，君心无事我心嗟。","玉楼人去春寥落，几对青灯念子华。"]},{"t":"寄黄锦章教授","f":"七言绝句","c":["同安烟柳杂晴川，江夏清风十丈莲。","此日相思头总白，几时重泛剡溪船。"]},{"t":"悼少傅先生","f":"七言绝句","c":["少小亲仁长事师，讲帷无复再趋期。","不眠此夜相思处，敢忘平生刻骨辞。"]},{"t":"赠吴生归觐钟陵","f":"七言绝句","c":["白发慈颜日倚闾，青灯游子正劬书。","朝来黄色眉端动，乾鹊声中庆有馀。"]},{"t":"郡庠潘梁二广文辱载酒偕往石井先陇小酌金石台而还","f":"七言绝句","c":["石井朝联二妙来，提壶兼历古名台。","长空溟漠收新雨，含笑江山畅一杯。"]},{"t":"除夜书怀兼柬子贞九韶","f":"七言律诗","c":["溪上寻梅归去迟，虚堂剪烛坐题诗。","精神已是龙钟后，涉历翻思少小时。","幸得简编常满眼，敢辞尘土暂侵衣。","家山旧有良朋约，试向东风一问之。"]},{"t":"戊辰元日","f":"七言绝句","c":["溪上寻梅雪乍晴，溪头流水已春声。","呼儿旋涤芸窗砚，准拟新诗颂太平。"]},{"t":"访子贞九韶同话胡二宅","f":"七言绝句","c":["帘户沉沉午梦馀，新晴天气景舒舒。","和风细拂家山袂，半日清谈故友庐。"]},{"t":"追次少傅先生寿日诗韵","f":"七言律诗","c":["花盛春城锦万枝，九天化日正迟迟。","运符圣德超千古，身幸儒冠际此时。","晨捧丝纶归玉署，夕陪鸳鹭泛金卮。","宿齐预拟明朝值，又悉丹诚向赤墀。"]},{"t":"挽盛山人","f":"七言律诗","c":["当年卜筑镇关心，绿水青山几访寻。","不有高人符往古，何由胜槩见于今。","图书映带供多趣，松竹周遭已茂林。","却念驿溪云黯淡，芒鞋何处觅登临。"]},{"t":"赠娄谅归上饶","f":"七言绝句","c":["稚志谆谆在广居，贤侯盛德远吹嘘。","独怜樗散空衰迈，丽泽何时重起予。"]},{"t":"壁沼以禦獭诸生咸用力焉诗以纪其成","f":"七言绝句","c":["躬事胼胝少长同，忽于平地见崇墉。","溶溶春碧歌于牣，不日还应懋尔功。"]},{"t":"赠周文东归","f":"七言绝句","c":["日讲残经味正奇，告归情急忽依依。","人生万事无不有，细诵前贤素位辞。"]},{"t":"程庸以种湖所书拙字及鄙句见示怅然有作","f":"七言绝句","c":["陈迹依稀慨昔游，寒窗遥夜意悠悠。","他年萍水重相念，何处西风独倚楼。"]},{"t":"赠王九鼎还五峰","f":"七言绝句","c":["四年三度款柴荆，更笃良朋永夜情。","别恨又添他日梦，生涯何处一浮萍。"]},{"t":"溪上偶成","f":"七言绝句","c":["偶尔閒行绕碧溪，梅花开处咏多时。","固知道理平铺在，方寸何容半点私。"]},{"t":"元日怀感","f":"七言绝句","c":["长风半夜卷顽云，霁色曈昽映雪分。","又感一元新惠泽，微吟随处咏洪钧。"]},{"t":"哭黄季恒","f":"七言绝句","c":["高谊真情三十年，老怀何忍诀终天。","茫茫石马江头路，冻雨寒云倍黯然。"]},{"t":"石泉开田","f":"七言绝句","c":["风雨潇潇小满天，四山蓑笠事新田。","个中会得艰难意，细和豳风七月篇。"]},{"t":"病中有怀子贞九韶","f":"七言绝句","c":["老病怀思只故人，故人疾病总酸辛。","如何得似平康步，选胜寻幽处处亲。"]},{"t":"访表兄锁秉端伯仲","f":"七言绝句","c":["同里同年斋更同，半生多故各西东。","清谈偶得三人共，两鬓萧疏总是翁。"]},{"t":"访表兄章二伯仲","f":"七言绝句","c":["长忆先君念母家，惭予小子近如遐。","幸陪花萼相辉好，更喜螽斯世泽赊。"]},{"t":"小儿鸣琴","f":"七言绝句","c":["竹树交加转午阴，衣冠秩秩夜沉沉。","雪泥鸿爪他年梦，记得从容抱此琴。"]},{"t":"赠李生归觐","f":"七言绝句","c":["曾于道上瞻乔木，他日遗文话大陂。","吊古未遑重策马，西风先唱觐亲词。"]},{"t":"牧归马上口号","f":"七言绝句","c":["挂角残经一解颐，秋风淅淅日斜晖。","会心偶尔微吟好，又向清流饮马归。"]},{"t":"九日同九韶饮子贞宅","f":"七言绝句","c":["平生佳节嗜狂吟，中岁方知学养心。","不问菊花开与未，无端新兴为君深。"]},{"t":"寄李宜之","f":"七言绝句","c":["城北南庄入梦频，岁华偏感老怀新。","孤吟辗转寒窗雨，尊酒何时共若人。"]},{"t":"客夜述怀","f":"七言绝句","c":["辗转才安枕屡惊，金鸡忽送五更声。","江枫细雨斜风梦，总是衰龄悼古情。"]},{"t":"大同原牧归后坊道中口占授小儿及曾正","f":"七言绝句","c":["斜穿香稻度秋山，细讲残经午始还。","幸际时雍身少恙，明朝依旧此开颜。"]},{"t":"题小塘茅屋","f":"七言律诗","c":["茅屋何年占小塘，宋元甲子几星霜。","清门种德高徵士，紫诰推恩秩侍郎。","快睹云来绳步武，能令山水益辉光。","一经从此尤珍重，日向兰阶迓百祥。"]},{"t":"游禅峰","f":"五言古诗","c":["孟春时物泰，条风应新律。","良辰岂重来，嘉会那可忽。","膏车饬谢屐，小子伊畴匹。","幽赏历岖嵚，胜览穷崷崒。","慕陶得自然，鄙殷怪空咄。","咏归欢未央，重游更何日。"]},{"t":"游南冈及下陂山水","f":"五言古诗","c":["朝出萝溪阪，夕返莲塘曲。","烟树眺参差，冈峦媚重复。","道泰物本小，虑澹意自足。","山人留酌斟，旧侣论心腹。","归来美清夜，云和畅寒玉。"]},{"t":"小憩觉溪徐氏","f":"五言绝句","c":["昔诵前贤传，今即高人居。","奉亲贤子孙，努力躬三馀。"]},{"t":"登黄柏最高峰","f":"五言古诗","c":["局促倦埃氛，游衍稀俦侣。","骥子能娱人，慕韩耽岣嵝。","青天卷片云，春山霁寒雨。","杖策不知疲，鱼贯何容与。","遂跻凌霄峰，徘徊以延伫。","长空极遐瞩，松阴相款语。","日昃憺忘归，清风助高举。"]},{"t":"牧黄岚坑","f":"五言古诗","c":["朝来抱微疴，残编减新课。","出门怅何之，言归无所作。","忽乘谷口兴，偶此崇冈坐。","契彼造化微，觉我颓龄惰。","振衣发啸歌，烟村夕阳堕。"]},{"t":"游黄岚坑","f":"五言古诗","c":["桃李薰太和，晴光烂如许。","宁知明日花，不有宵来雨。","芳原纵游衍，呼童供笑语。","徘徊绿萝峰，怅望清溪溆。","皞皞固同胞，熙熙尽吾与。","悟彼静者心，乐此动时趣。","烟村归去迟，瞑色迷云墅。"]},{"t":"游黄岚坑","f":"五言古诗","c":["微雨霁芳原，散步春溪曲。","欢呼及童竖，策马驱黄犊。","入崦竹翛翛，面冈杉簇簇。","展我怀中书，坐向林间读。","不有巢许心，那知箕颍躅。","但得风日佳，朝朝来此牧。"]},{"t":"牧转冈头","f":"五言古诗","c":["搴裳陟崔嵬，沉吟不知去。","尘襟顿萧散，逸兴迷云树。","梅残谁氏花，麦涨朝来雨。","邻牧左右来，往事更相语。","预期明日晴，重作青山侣。"]},{"t":"游龙门七宝寺","f":"五言古诗","c":["病躯惬初景，动息颇自由。","不息风雨倦，来贪山水幽。","穿云路窈窕，抟空行遭周。","危峰杰笔卓，叠嶂翠屏稠。","契我遗世想，遂此物外游。"]},{"t":"素庵题正统辛酉冬予归自钟陵息肩湖莽李氏南溟饬其宗以迓礼于从子世熙之堂崔氏文瓛翁古服来临酒数行欢然赋诗而别后七年南溟脩世谱话旧小陂索素庵大书以归又二年持以求赋诗曰","f":"七言绝句","c":["一点虚灵天地参，忍将至贵堕春酣。","请看天泽初爻旨，是我蓍龟与指南。"]},{"t":"题厉斋","f":"七言绝句","c":["韦弦何用佩诸身，矫枉扶偏各有因。","细向堪舆观万物，反躬皆足熟吾仁。"]},{"t":"不寐","f":"五言绝句","c":["愁来不成梦，梦回心耿耿。","定力嗟学微，长夜谁予警。"]},{"t":"同熊生渤牧后坊因登绝岭","f":"五言古诗","c":["节候适清和，田家雨新足。","芳林牧马来，露草萋以绿。","乃有儒一生，吾伊荫脩竹。","畅我仁知心，跻攀散遐躅。","一览长天云，真趣良可掬。"]},{"t":"同诸生游阴源","f":"五言律诗","c":["山水夙所歆，朋游固其好。","风雨虽滞淫，穷源竟须到。","幽意蔚沉沉，归怀晴浩浩。","良辰不可常，更拟山阴棹。"]},{"t":"新堂即事","f":"五言律诗","c":["平生山水心，于焉得休卜。","一堂虽甚卑，素意良自足。","坐看风雨来，已喜无沾漉。","赋诗纪吾成，古人有芳躅。"]},{"t":"题凝翠字后","f":"五言绝句","c":["游衍趁良时，欢心慕浴沂。","饱眈山水趣，书罢更留诗。"]},{"t":"登连珠峰","f":"五言古诗","c":["阁中罢鸣琴，芳筵谢斟酌。","扪萝一褰裳，奇峰酬素约。","天风起萧条，山雨来溟漠。","时驰千里目，四际云烟薄。","会当斯结亭，胜览翔寥廓。"]},{"t":"同诸生游倒桐塍","f":"五言古诗","c":["东皋霁甘泽，我心日悠悠。","出门玩时物，因之白云丘。","行行不知远，遂历群峰头。","浩歌酣万态，斜景风飕飕。","眷言顾诸子，去矣仍夷犹。","渺然出尘想，奇功归一游。"]},{"t":"沼上编茅为亭取程子秋日之诗名曰自得夜坐其中因成此句","f":"五言古诗","c":["幽怀不能寐，揽衣造新亭。","曲池湛华月，芳树还冥冥。","群峰远映带，一水近回萦。","坐久欢未竟，夜迥气逾澄。","寂感玄化微，伊洛歆馀馨。"]},{"t":"夏日偶成","f":"五言古诗","c":["卧疴止衡门，何以娱长日。","卷舒架上书，游戏閒窗笔。","南亩课农馀，东园薙蔬毕。","务我分宜然，无劳知难必。","道泰身自亨，作德心斯逸。","长歌书座隅，庶用箴吾失。"]},{"t":"游石牛埠","f":"七言绝句","c":["时止时行任自然，离离香稻小春天。","微踪何足符佳梦，自是民彝笃好贤。"]},{"t":"赠别熊崇义","f":"七言绝句","c":["不惮风霜跋涉遥，翩然来访白云桥。","嘉宾盛处归怀好，茂对良辰话久要。"]},{"t":"题李章勉学斋","f":"七言绝句","c":["浮生事业易蹉跎，百岁光阴定几何。","不觉秋霜空满鬓，玩君华扁谩高歌。"]},{"t":"携小儿方家坪拜先陇","f":"七言绝句","c":["方家坪侧接连塘，二代铭旌托此藏。","孱薄每惭荒世德，阃仪空感孝思长。"]},{"t":"寄朱孟真教谕","f":"七言绝句","c":["青春桃李忆成均，两造高门剑水滨。","闻说轩车能我顾，无端旧梦欲书绅。"]},{"t":"杨溪故居","f":"七言绝句","c":["童稚长怀故里居，顾瞻茂草向桑榆。","溪头细接云仍话，勉尔重新教子书。"]},{"t":"曲冈道中","f":"七言绝句","c":["疋马寒村偶独过，壮怀莫景怅如何。","梅花满眼无人问，谩对虬枝一放歌。"]},{"t":"狭原洪氏","f":"七言绝句","c":["芒鞋又作葛天民，童冠追随五六人。","绿树池塘投辖处，梅花如雪昼如春。"]},{"t":"雪夜偶成","f":"七言绝句","c":["四檐风雪夜漫漫，独拥残炉对岁寒。","细忆晏庭诗思切，是知仁者敢偷安。"]},{"t":"中原桥黄氏","f":"七言绝句","c":["忆年童稚饱经过，半百光阴奈若何。","万事悠悠空白发，一怀慷慨为君歌。"]},{"t":"溪上偶成","f":"七言绝句","c":["万缘由命不须嗟，遮莫飞腾莫景斜。","偶度小桥流水曲，缓从梅下玩孤花。"]},{"t":"读韩子","f":"七言绝句","c":["重云密雨锁春寒，病思无端强自宽。","逝矣古人心独在，遗编一一静中看。"]},{"t":"寄谢王医博高危诸医士李王诸亲友","f":"七言绝句","c":["骥子南游学舜弦，春城淹疾友琴轩。","神功深赖阳和力，青眼频烦故旧怜。"]},{"t":"题黄氏花萼楼","f":"七言绝句","c":["神京曾忝仲联行，乡国相于季氏良。","花萼楼深春昼永，自天多福一穰穰。"]},{"t":"题水竹居","f":"五言古诗","c":["结架媚閒旷，夐然面寥廓。","水环白云隈，竹带青山郭。","云霞生我衣，鱼鸟同人乐。","曰予固静者，煮茗相宾客。","意遣憺忘归，会心溺洒落。","缅怀恍如梦，赋诗酬旧约。"]},{"t":"程庸承府主命李观光章取则皆集小陂讲颜子喟然之章，赋此以勉焉","f":"七言绝句","c":["二生忽喜后先来，无德相资愧尔才。","黄卷有师当自勉，关闽濂洛是梯阶。"]},{"t":"牧大同原杨林坑即事","f":"五言古诗","c":["既辍黄岚游，却入同原嬉。","三阳时向交，暖律回春晖。","人情惜旧好，物熊含新辉。","悠哉四圣心，静向林间窥。","单骑日日来，飘飘澹忘归。","偶携二三子，丽泽同箴规。"]},{"t":"与杨珉游大同原","f":"五言古诗","c":["林西日月长，讲罢无馀事。","东皋策吾马，聊尔川原憩。","风景惟暮春，烟芳媚初霁。","理会尘外心，道酣淡中味。","惠然嘉友来，共此无怀世。"]},{"t":"枕上作","f":"七言绝句","c":["萧然陋巷日希颜，独把遗经静处摊。","准拟朝来风日好，遍随晴色踏青山。"]},{"t":"以事入城假宿西廨彭氏","f":"七言绝句","c":["细雨斜风困马蹄，年过六十未知非。","客窗辗转难成寐，定力何能一庶几。"]},{"t":"暂寓程庸氏屈府主王侯贲临夜承郎君伴宿","f":"七言绝句","c":["春风堂上降鸾凰，瑞气祥烟日正长。","翠竹碧梧歌不足，高烧银烛夜煌煌。"]},{"t":"閒中偶述","f":"七言绝句","c":["花木沈沈庭寂寂，苍苔尽日稀行迹。","支赜窗下一沈吟，人间几片韩山石。"]},{"t":"绝句","f":"七言绝句","c":["一棚新架白云端，四达天风九夏寒。","野性惯随樵牧侣，时时来此独危冠。"]},{"t":"东坑幽涧","f":"七言绝句","c":["一水泠泠逗密林，无名花草匝幽阴。","苔矶终日不知暑，涤尽平生扰扰心。"]},{"t":"题菊窗","f":"七言绝句","c":["清霜篱落任天真，可信虚窗别有春。","陶屈依稀千载后，餐英裛露岂无人。"]},{"t":"宿熊玑氏","f":"七言绝句","c":["江湖远适为求医，首寓高斋惬故知。","良夜好天忘倦处，清风明月细谈诗。"]},{"t":"发孔家渡","f":"七言绝句","c":["茫茫新涨漾晴洲，华发宁知非胜游。","未了平生山水债，又从临汝附扁舟。"]},{"t":"次打石港","f":"七言绝句","c":["当年曾此泊晴湾，细读邹书向夜残。","始信万缘端有命，欲为君子却诚难。"]},{"t":"哭傅秉彝","f":"七言绝句","c":["独步来寻洗墨池，秋风禾黍正离离。","一丘旧隐成春梦，非恸夫人而为谁。"]},{"t":"守风青草洲","f":"七言绝句","c":["青草洲边几日留，风来北极正飕飕。","个中欲问行藏意，未达中庸是我忧。"]},{"t":"荅舟人","f":"七言绝句","c":["徒窃虚名实陆沈，慇勤空负秉彝心。","那由回得西风驭，截日深功断自今。"]},{"t":"南康舟中","f":"七言绝句","c":["满怀今古怅悠悠，举目江山尽胜游。","华发又堪来几度，可无新句咏清秋。"]},{"t":"志喜","f":"七言绝句","c":["袅袅风帆快客程，良朋时共话平生。","忽惊蜀浪半江浊，又接淮山一带青。"]},{"t":"重宿南庄","f":"七言绝句","c":["四十年前此寓居，华颠重宿意何如。","不堪潦倒浑无似，谩托狂歌寄我吁。"]},{"t":"龙井道中","f":"五言绝句","c":["石壁话龙湫，青山梦里游。","长亭新霁雨，随处咏高秋。"]},{"t":"次练潭","f":"五言绝句","c":["半野云烟薄，长空新月多。","息肩知有处，灯火练潭河。"]},{"t":"横山双港道中","f":"五言绝句","c":["晴色添诗况，山名认上音。","无劳乡国梦，日咏古人心。"]},{"t":"阁中即事","f":"古风","c":["尽日文章慨作家，?冥楼阁寂无哗。","云山时独揽秋色，风露谁同玩月华。"]},{"t":"窗间独坐","f":"五言绝句","c":["阁上诗应罢，窗间月复明。","好怀未忍寐，端坐忆平生。"]},{"t":"赠江渊","f":"七言绝句","c":["久重才华识俊英，偶从此地共茅亭。","几时更对何乡榻，细写江东渭北情。"]},{"t":"八月十二夜何家圩玩月","f":"七言绝句","c":["访古微私不易酬，心期江汉日悠悠。","行藏信有平生分，谩向凉天咏素秋。"]},{"t":"墙下对淮山独坐","f":"七言绝句","c":["徐步閒来藉草吟，淮山面面感人深。","若为飞度晴岚表，一览中原畅夙心。"]},{"t":"十四夜同李进士玩月","f":"七言绝句","c":["别却乡园纵远观，前期浩荡路漫漫。","何如今夜高秋月，万里清光此共看。"]},{"t":"别何家圩道中口占授宜之","f":"七言绝句","c":["昨夜巡檐同霁月，今朝联辔共秋山。","恍思三十年前梦，信是人生会合难。"]},{"t":"寄赠李春","f":"七言绝句","c":["天柱峰前忆旧知，江湖秋兴总如飞。","金台早得春消息，好寄东风汝水西。"]},{"t":"贻南庄李氏","f":"七言绝句","c":["淮水秋风归兴浓，片帆日指大江东。","满门长幼俱青眼，华发何时又一逢。"]},{"t":"独步江岸","f":"七言绝句","c":["江岸逶迤独步来，日光恰喜密云开。","能消几两南风力，咫尺青霄是凤台。"]},{"t":"次西梁矶","f":"七言绝句","c":["西梁矶下系孤蓬，矶自峨峨水自东。","蓂荚不知经几换，几人曾此咏和风。"]},{"t":"登西梁矶尾","f":"七言绝句","c":["暂纵棱层咫尺踪，江山一览已增雄。","脱令病骨生轻翰，飞步危巅又不同。"]},{"t":"江边独步","f":"七言绝句","c":["咫尺金陵到尚难，朔风犹未退狂澜。","平芜渺渺不知处，独数江南江北山。"]},{"t":"具庆堂为桐城黄金题","f":"七言绝句","c":["爱汝清溪寿二亲，云笺晴染坐生春。","九天会沐恩波阔，戏綵堂前百福新。"]},{"t":"永感堂为桐城朱善题","f":"七言绝句","c":["欲报劬劳慨昊天，青灯耿耿思绵绵。","顾我旧游挥客泪，与君同废蓼莪篇。"]},{"t":"别金陵道次五显旧游口占授章余李三友","f":"七言绝句","c":["客中欣遇二三生，送送无端故国情。","佳丽山川同一览，楼台高下凤凰城。"]},{"t":"旅次晓立","f":"七言绝句","c":["江湖日夜数归期，乾鹊声声晓为谁。","篱菊忽惊银灿烂，畦蔬时接翠葳蕤。"]},{"t":"次东馆头","f":"七言绝句","c":["侵星问道高桥侧，斜日息肩东馆头。","欲卜前程知有在，霁行潦止不须愁。"]},{"t":"宿杜家村","f":"七言绝句","c":["杜家桥外杜家村，细雨斜风暮到门。","多谢主人怜老大，盘飧杯酒夜温存。"]},{"t":"句容樊知州宅","f":"七言绝句","c":["饱听邦民颂去思，玉楼人去已多时。","阳春白雪惭吾辈，流水高山吊子期。"]},{"t":"宿徐村","f":"七言绝句","c":["跋涉泥途不惮劬，晚晴又得旅怀舒。","清溪濯足看山罢，松竹林头认寓居。"]},{"t":"宿案头","f":"七言绝句","c":["癖性从来厌市墟，息肩时托近乡居。","金风禾黍秋连野，绿柳池塘月照庐。"]},{"t":"发丹阳","f":"七言绝句","c":["遥牵高缆别丹阳，明日青山指浙江。","谓我何求宁足校，寸心对越是苍苍。"]},{"t":"舟中九日","f":"七言绝句","c":["去年九日遥思子，今日重阳子忆亲。","自昔怀居非达士，由来安土属吾人。"]},{"t":"吕城坝","f":"七言绝句","c":["云散青霄月放明，时闻前岸浩歌声。","平生湖海希踪迹，始向丹阳识坝名。"]},{"t":"戚墅铺","f":"五言绝句","c":["晴穫农人喜，安流舟子閒。","平林戚墅铺，迥野浙西山。"]},{"t":"苏州绝句次唐诗韵 其一","f":"七言绝句","c":["万态循环故复新，尘寰知换几回春。","我来又发姑苏咏，可信浮沤等昔人。"]},{"t":"苏州绝句次唐诗韵 其二","f":"七言绝句","c":["斜风细雨菊花天，今夜何知此水眠。","他日旧乡谈旧迹，青山却意梦中船。"]},{"t":"过吴江县","f":"五言绝句","c":["一棹吴江上，寒烟枫落时。","无才堪赋咏，聊诵古人诗。"]},{"t":"次嘉兴","f":"七言绝句","c":["程程客路问前踪，又系城头槜李篷。","怀古心期何处写，一江烟浪雨冥濛。"]},{"t":"舟中晓望","f":"七言绝句","c":["吴江欲尽越山来，东日融融霁景开。","桑柘稻粱连沃壤，人烟村落在无怀。"]},{"t":"长安坝","f":"七言绝句","c":["崇德桥头暮刺船，迢迢江岸带星牵。","长安坝上停篙处，杨柳阴中伴月眠。"]},{"t":"望越中山","f":"七言绝句","c":["牵路晴明不惮难，船头时见越州山。","前程信有自然妙，莫把天心当等閒。"]},{"t":"平林舟中 其一","f":"七言绝句","c":["尽日舟行不见山，离离香稻映柴关。","倚篷独咏凝晴望，何处云端一翠鬟。"]},{"t":"平林舟中 其二","f":"七言绝句","c":["平林山后又看山，知在钱塘胜槩间。","老大薄游颜独厚，绝无新句脍人寰。"]},{"t":"昼梦觉作","f":"七言绝句","c":["一枕平安昼梦浓，起题红叶数青松。","老于世态无心处，到处身疑是梦中。"]},{"t":"钱塘绝句","f":"七言绝句","c":["曾拟钱塘吊古词，薄游今乃戏于斯。","西风何限平生思，斜日从谁一咏之。"]},{"t":"钱塘留柬程庸","f":"七言律诗","c":["准拟名山复并游，朔风无奈日飕飕。","金陵已失连枝喜，吴会仍为落叶愁。","南指片帆应迅速，北来行李莫淹留。","丹枫黄菊同归梦，定约三衢与信州。"]},{"t":"观湖","f":"七言绝句","c":["先声隐隐远如雷，高浪排空雪作堆。","欲记新题何处写，伊谁一醉菊花杯。"]},{"t":"发钱塘","f":"七言绝句","c":["乡音无寐共清宵，得伴何妨归路遥。","夜半开头更唤梦，月明如昼竞乘潮。"]},{"t":"即事","f":"七言绝句","c":["西风凄切湿云多，东日朦胧午始和。","佳菊丛丛谁采撷，好山处处自吟哦。"]},{"t":"子陵钓台","f":"七言绝句","c":["王孙旧是布衣伦，岁晚如何又屈身。","不有先生高致在，滔滔俱羡拂须人。"]},{"t":"即事","f":"七言绝句","c":["歌声才罢又箫声，畅我孤篷客里情。","他日欲知牵路处，丹枫黄菊乱山青。"]},{"t":"大浪滩","f":"七言绝句","c":["先君遗墨识名滩，使节曾经此往还。","改罢新诗吟未了，舟人又指富春山。"]},{"t":"近衢州","f":"七言绝句","c":["水原将尽话西江，红叶归心日夜忙。","犹爱越山看不饱，焉知孤棹尚他乡。"]},{"t":"过衢州","f":"五言绝句","c":["夜半朔风遒，滩声急去舟。","推篷云月里，髣髴看衢州。"]},{"t":"题徐氏村居","f":"七言律诗","c":["跋涉遥寻玩易踪，幽栖近在县南峰。","松篁共听今宵雨，礼乐多存太古风。","俛仰浮生一梦寐，相看华发两龙钟。","酒酣细和辛夷什，丹桂丛兰思正浓。"]},{"t":"别徐希仁","f":"七言绝句","c":["彼此浮生类转蓬，青山端似梦中逢。","明朝努力加餐饭，又隔南云少便鸿。"]},{"t":"常山道中","f":"七言绝句","c":["后先已喜轿咿哑，驿路泥乾不惮赊。","回首故人程渐远，青山从此白云遮。"]},{"t":"玉山舟中","f":"七言绝句","c":["独坐船头爱日光，好风又喜片帆扬。","云山簇簇缘谁碧，岸菊丛丛为我黄。"]},{"t":"与周文娄谅二生","f":"七言绝句","c":["自叹虚名忝士林，慇勤孤负二生心。","莫云春树他年梦，杰阁高轩记短吟。"]},{"t":"发广信","f":"七言绝句","c":["双棹飘飘逐急流，青衫独自立沙头。","明朝矫首东云外，须忆云峰是胜游。"]},{"t":"晓发","f":"七言绝句","c":["舟师晴唤急前程，短棹侵星带月明。","却忆宵来何处宿，孤衾和梦听歌声。"]},{"t":"宿横石","f":"五言绝句","c":["横石冈头路，人疲日又斜。","平林茅屋近，有店即为家。"]},{"t":"次上清","f":"五言绝句","c":["迢迢还乡路，程程日逐西。","鸡鸣时问境，十里是金溪。"]},{"t":"野桥小憩","f":"五言绝句","c":["晴日催归路，平桥又息躬。","云峰四面碧，霜叶一溪红。"]},{"t":"孔方道中","f":"五言绝句","c":["逆旅程难进，疲肩重日增。","归期无用数，俛首事孤征。"]}]};